      "path": "dsh-pet/src/host/index.ts",
      "content": "/**\n * 插件入口：Cordis 插件，把 host 半侧的配置、路由、斜杠命令、轮询与桌面 Helper 装配到 ctx。\n * 装配顺序不能改：`getHandlePetRoute` 惰性取用（`httpRoute` 在本函数后段才创建），`startHelper` 必须最后调用。\n * @module dsh-pet/src/host/index\n */\nimport { createHostSetup } from './plugin/setup.ts';\nimport { readAllConfig } from './config.ts';\nimport { createHttpRoute, registerHttpRoute } from './plugin/http-route.ts';\nimport { registerLifecycle } from './plugin/lifecycle.ts';\nimport { registerChatCommand } from './plugin/command-chat.ts';\nimport { registerPetCommand } from './plugin/command-pet.ts';\nimport { registerLoops } from './plugin/loops.ts';\nimport { registerBalanceCommand } from './plugin/command-balance.ts';\nimport { registerSessionWatch } from './plugin/session-watch.ts';\nimport { createDesktopHelper } from './plugin/desktop-helper.ts';\nimport { createBalancePoll } from './plugin/balance-poll.ts';\nimport { createChatMemory } from './plugin/chat-memory.ts';\nimport { createSessionNotify } from './plugin/session-notify.ts';\nimport { createPetLookup } from './plugin/pet-lookup.ts';\nimport { createDownloadReport } from './plugin/download-report.ts';\nimport { createWorkStatusBridge } from './plugin/work-status-bridge.ts';\nimport { registerTodoReminders } from './plugin/todo-reminders.ts';\nimport { createVoiceService } from './voice/speak.ts';\nimport { createHearService } from './voice/hear.ts';\nimport { TODO_FILE_NAME, TodoStore } from './todo/store.ts';\nimport { join } from 'node:path';\nimport type { PetRouteDeps } from './routes/types.ts';\n\n/** 插件行 id（与 cordis.patch.yml 一致） */\nexport const name = 'pet';\n/** 需要注入的服务：webServer（路由）+ agentDefaultModel（当前服务商）+ credentials（凭证）+ llm（对话模型调用）+ commands（/balance 斜杠命令）+ connection（桌面 Helper「打开 AI 设置」用的已鉴权站点 URL） */\nexport const inject = ['webServer', 'agentDefaultModel', 'credentials', 'llm', 'commands', 'connection'];\n\n/** 宿主插件主体：注册 `/dsh-pet-7340` 前缀路由与斜杠命令（/balance /pet /chat）；ctx 暂用 any（peer 类型包本地不可解析）。 */\n// eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入的 ctx（webServer/locale 等 service 无静态类型）\nexport function apply(ctx: any): void {\n  const setup = createHostSetup(ctx);\n  const {\n    userRoot,\n    log,\n    configPaths,\n    thumbUserRoot,\n    memeDirsFor,\n    standaloneAiPolicy,\n    state,\n    playback,\n    workStatus,\n    EXTERNAL_WORK_SESSION,\n    nextExternalWorkSeq,\n  } = setup;\n  const workStatusBridge = createWorkStatusBridge({ state, workStatus });\n  const { publishWorkStatus, stopWorkStatusFlush } = workStatusBridge;\n  const downloadReport = createDownloadReport({\n    EXTERNAL_WORK_SESSION,\n    nextExternalWorkSeq,\n    publishWorkStatus,\n    workStatus,\n  });\n  const { reportDownload, stopDownloadSlotTimer } = downloadReport;\n  const petLookup = createPetLookup({ state, configPaths });\n  const { lock, sleep, sleepRefusalText } = petLookup;\n  const sessionNotify = createSessionNotify({ ctx, publishWorkStatus, state, workStatus });\n  const {\n    pushNotifyFrame,\n    turnFlags,\n    terminalTimers,\n    lastTodoText,\n    lastReplyText,\n    toolsInFlight,\n    cancelTerminalCleanup,\n    scheduleTerminalCleanup,\n    notifyActivityTimers,\n    scheduleCompletionNotify,\n  } = sessionNotify;\n  const chatMemory = createChatMemory({ ctx, configPaths, log, memeDirsFor, playback, state, userRoot });\n  const { lastWhisperAt, publishWhisper, publishSleepTalk, chatWithPet, getActivePetId, setActivePetId } = chatMemory;\n\n  const balancePoll = createBalancePoll({ ctx, configPaths, getActivePetId, log, state });\n  const { effectivePetList, balancePeriodSec, whisperPeriodSec, refreshBalance, resolveActivePetId, petDisplayName } =\n    balancePoll;\n\n  // 待办清单：一份用户级数据（不分宠物），落盘在插件数据根；提醒循环与 /todos 路由共用同一个实例。\n  const todos = new TodoStore({ file: join(userRoot, TODO_FILE_NAME), log });\n\n  const desktopHelper = createDesktopHelper({\n    ctx,\n    configPaths,\n    effectivePetList,\n    log,\n    reportDownload,\n    thumbUserRoot,\n    // 惰性取用：handlePetRoute 在下方装配，Helper 只在启动/收请求时才真正调用它\n    getHandlePetRoute: () => httpRoute.handlePetRoute,\n  });\n  const { startHelper, stopHelper, markDisposed } = desktopHelper;\n\n  const deps: PetRouteDeps = {\n    ...setup,\n    ...petLookup,\n    ...workStatusBridge,\n    ...chatMemory,\n    ...balancePoll,\n    ...desktopHelper,\n    ...sessionNotify,\n    ctx,\n    todos,\n    // 语音合成：缓存落 userRoot，失败只留日志，不打断宿主\n    voice: createVoiceService({ userRoot, log }),\n    // 语音识别：能力来自宿主（DSH 的 speechToText），没启用时服务自己在调用时回 unsupported\n    speech: createHearService({ speechToText: () => setup.optionalService('speechToText') }),\n  };\n  const httpRoute = createHttpRoute(deps);\n  registerHttpRoute(ctx, httpRoute.handlePetRoute);\n\n  registerSessionWatch({\n    ctx,\n    cancelTerminalCleanup,\n    lastTodoText,\n    lastReplyText,\n    notifyActivityTimers,\n    publishWorkStatus,\n    pushNotifyFrame,\n    scheduleCompletionNotify,\n    scheduleTerminalCleanup,\n    terminalTimers,\n    toolsInFlight,\n    turnFlags,\n    workStatus,\n  });\n\n  registerBalanceCommand({ ctx, effectivePetList, refreshBalance, sleep, sleepRefusalText });\n\n  registerLoops({\n    ctx,\n    balancePeriodSec,\n    configPaths,\n    lastWhisperAt,\n    lock,\n    log,\n    publishWhisper,\n    publishSleepTalk,\n    refreshBalance,\n    sleep,\n    standaloneAiPolicy,\n    whisperPeriodSec,\n  });\n\n  registerPetCommand({ ctx, effectivePetList, petDisplayName, resolveActivePetId, setActivePetId });\n\n  registerChatCommand({ ctx, chatWithPet, log, publishWhisper, resolveActivePetId, sleep, sleepRefusalText });\n\n  // 待办提醒：随插件生命周期起停；锁被第三方持有时由 pickReminderSpeaker 跳过该宠物。\n  // 播报开关现读现用：改配置后下一次提醒即生效，不必重启。\n  registerTodoReminders({\n    ctx,\n    effectivePetList,\n    isVoiceTodoEnabled: () => readAllConfig(configPaths).main?.voiceTodoEnabled === true,\n    lock,\n    log,\n    sleep,\n    state,\n    todos,\n    waiterCount: () => state.waiterCount(),\n  });\n\n  registerLifecycle({\n    ctx,\n    lock,\n    markDisposed,\n    playback,\n    state,\n    stopDownloadSlotTimer,\n    stopHelper,\n    stopWorkStatusFlush,\n  });\n\n  // 路由就绪后拉起桌面 Helper（Electron 缺失时仅告警，不影响 DSH 与浏览器 overlay）\n  startHelper();\n}\n"
    },
    {
      "path": "dsh-pet/src/client/app.ts",
      "content": "/**\n * 浏览器半侧装配层：注入 react，组装宠物 overlay 与设置页，注册进 DSH 插槽。\n * 不负责页面业务：宠物页面在 pet.ts，设置页在 settings.ts。\n * 依赖 DSH 注入的 slots / locale / remote / commandUi 等 Cordis 服务。\n * 任何可选能力缺失都只降级功能，绝不让整个插件加载失败。\n * @module dsh-pet/src/client/app\n */\nimport { makePetUI } from './pet.ts';\nimport { readPose } from './pose.ts';\nimport { readProgress } from './progress.ts';\nimport { takeMenuEvents } from './menu-service.ts';\nimport { getStateSnapshot } from './state-service.ts';\nimport { dicts, makePetConfigSection, NS, petBridge } from './settings.ts';\nimport { initNotify } from './notify.ts';\nimport { installCommandFaces, type CommandFace, type CommandUiLike } from './command-faces.ts';\nimport { installSectionNavIcon } from './nav-icon.ts';\nimport { registerPetChatTab, openPetChatTab } from './chat/register.ts';\nimport { PET_CHAT_COMMAND_ID, registerPetChatShortcut } from './chat/shortcut.ts';\nimport { registerPetCardShortcuts } from './pet/card/shortcut.ts';\nimport type * as ReactNS from 'react';\nimport type * as PrimitivesNS from '@deepseek-ai/dsh-client-ui-primitives';\n\n/** 创建 DSH 插件 factory，返回带 name / inject / apply 的模块。 */\n// eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH __ModuleLoader__ 契约（f(require) => module），外部无静态类型\nexport function makeFactory(): (require: (mod: string) => any) => any {\n  return (require) => {\n    const module = { exports: {} };\n\n    const react: typeof ReactNS = require('react');\n    const { useEffect, useRef, useState, useCallback } = react;\n    const { jsx: h } = require('react/jsx-runtime');\n\n    // primitives 是平台种子模块；取不到只影响命令图标，不影响插件加载。\n    let primitives: typeof PrimitivesNS | undefined;\n    try {\n      primitives = require('@deepseek-ai/dsh-client-ui-primitives');\n    } catch (error) {\n      console.warn('[dsh-pet] 图标模块不可用：' + (error instanceof Error ? error.message : String(error)));\n    }\n\n    // react-dom 也是平台种子模块，仅用于把图标同步渲成 SVG 供 CSS mask 使用。\n    // 取不到就退化成齿轮图标，不影响插件加载。\n    let renderIconSvg: ((icon: ReactNS.ComponentType<PrimitivesNS.IconProps>) => string) | undefined;\n    try {\n      const { createRoot } = require('react-dom/client');\n      const { flushSync } = require('react-dom');\n      renderIconSvg = (icon) => {\n        const holder = document.createElement('div');\n        const root = createRoot(holder);\n        try {\n          // flushSync：root.render 是异步调度，不同步刷一次拿不到 DOM。\n          flushSync(() => root.render(h(icon, { size: 16 })));\n          return holder.innerHTML;\n        } finally {\n          root.unmount();\n        }\n      };\n    } catch (error) {\n      console.warn(\n        '[dsh-pet] 图标渲染器不可用（react-dom 缺失）：' + (error instanceof Error ? error.message : String(error)),\n      );\n    }\n\n    // 宠物 overlay 与设置页各自独立成文件，这里只组装和注册。\n    const PetMulti = makePetUI({ h, useState, useEffect, useRef });\n\n    const name = 'pet';\n    // commandUi 声明为服务依赖，确保「/」命令服务就绪后才 apply，/pet 装饰必然注册成功。\n    const inject = ['slots', 'locale', 'connection', 'remote', 'remote.commands', 'commandUi'];\n    // eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入的 ctx（locale/slots/webServer 等 service 无静态类型）\n    function apply(ctx: any) {\n      // 设置页文案字典。\n      ctx.effect(() => ctx.locale.register(NS, dicts), 'dsh-pet: dictionaries');\n      const t = ctx.locale.bind(NS);\n\n      // 同页第三方插件可通过 Cordis 服务 petApi7340 读取本页宠物的实况、播放进度、最近一拍状态与菜单点击。\n      // 只开读，控制仍走 HTTP，避免出现两条控制通道。\n      // 服务名带 7340 后缀避免与生态里的同名服务冲突；Cordis 同名 provide 会直接抛错。\n      // 消费者用 ctx.get('petApi7340') 探测，拿不到就是老版本；`getState` / `menuEvents` 也要单独探测（老版本没有它们）。\n      ctx.provide('petApi7340', {\n        getState: getStateSnapshot,\n        menuEvents: takeMenuEvents,\n        pose: readPose,\n        progress: readProgress,\n      });\n\n      // 系统通知：host 把通知帧写进 /state 的 sections.notify，统一轮询发现变化后弹 toast。\n      ctx.effect(\n        () =>\n          initNotify({\n            // 惰性取服务：它可能晚于本插件注册；缺失时退化为只把窗口叫回前台。\n            // eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入服务无静态类型\n            openSession: (sessionId: string) => (ctx as any).get?.('uiWorkspace')?.openSession?.(sessionId),\n            // 通知标题用会话名：会话列表里那一行的 title；空白会话 / 未命名会话取到空串就返回 undefined。\n            sessionTitle: (sessionId: string) => {\n              // eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入服务无静态类型\n              const row = (ctx as any).get?.('sessions')?.list?.getSnapshot?.()?.byId?.[sessionId];\n              const name = typeof row?.title === 'string' ? row.title.trim() : '';\n              return name || undefined;\n            },\n          }),\n        'dsh-pet: notifications',\n      );\n\n      // /pet 选择框：选中后提交 /pet <id>，由 host 命令落地。\n      // commandUi 已是服务依赖，但仍保留缺失时的降级提示。\n      ctx.effect(() => {\n        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入服务无静态类型\n        const commandUi = (ctx as any).get?.('commandUi');\n        if (!commandUi || typeof commandUi.decorate !== 'function') {\n          console.warn('[dsh-pet] 命令选择框不可用：commandUi 服务缺失（/pet 仍可手输 id 或名字）');\n          return () => {};\n        }\n        return commandUi.decorate({\n          name: 'pet',\n          available: () => true,\n          ui: {\n            kind: 'popupSelect',\n            // 选项来自当前生效宠物列表，name 已兜底。\n            options: async () =>\n              petBridge.current.map((p) => ({\n                id: p.id,\n                label: p.name || p.id,\n                detail: (p.assetRoot && p.assetRoot !== p.id ? p.assetRoot + ' / ' : '') + p.id,\n              })),\n            // 选中后提交 /pet <id>，由 host 校验并设置当前桌宠。\n            onSelect: async (option: { id: string }, session: { sessionId: string }) => {\n              // eslint-disable-next-line @typescript-eslint/no-explicit-any -- remote 无静态类型\n              await (ctx as any).remote?.commands?.execute(session.sessionId, '/pet ' + option.id, []);\n            },\n          },\n        });\n      }, 'dsh-pet: /pet picker');\n\n      // 给 /chat /pet /balance 补上「/」菜单的行标题与图标。\n      // DSH 没有官方入口，这里包装 commandUi.candidates；命令本身的行为不受影响。\n      // 依据与降级策略见 command-faces.ts。\n      ctx.effect(() => {\n        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- DSH 注入服务无静态类型\n        const commandUi = (ctx as any).get?.('commandUi') as CommandUiLike | undefined;\n        const icons = primitives;\n        if (commandUi === undefined || icons === undefined) {\n          console.warn('[dsh-pet] 命令图标不可用（命令本身仍可用，只是没有图标）');\n          return () => {};\n        }\n        return installCommandFaces(\n          commandUi,\n          new Map<string, CommandFace>([\n            // 对话气泡：94 个内置图标里唯一的纯对话气泡。\n            ['chat', { label: () => t('cmd.chat'), icon: icons.IconQueueOutlineRegular }],\n            // 双人形：从多只桌宠里挑一只。\n            ['pet', { label: () => t('cmd.pet'), icon: icons.IconUsersOutlineRegular }],\n            // 仪表盘：额度与用量。\n            ['balance', { label: () => t('cmd.balance'), icon: icons.IconGaugeOutlineRegular }],\n          ]),\n        );\n      }, 'dsh-pet: command faces');\n\n      // 设置页导航「桌宠配置」的图标：DSH 只给白名单分区配图标，只能在 DOM 层补。\n      // 依据与降级策略见 nav-icon.ts。\n      ctx.effect(() => {\n        const renderIcon = renderIconSvg;\n        const icon = primitives?.IconSlidersTwoOutlineMedium;\n        if (renderIcon === undefined || icon === undefined) {\n          console.warn('[dsh-pet] 设置页导航图标不可用（那一行仍是齿轮）');\n          return () => {};\n        }\n        return installSectionNavIcon({ label: () => t('nav'), renderSvg: () => renderIcon(icon) });\n      }, 'dsh-pet: settings nav icon');\n\n      // 宠物 overlay：容器渲染多个 PetCard。\n      ctx.slots.inject('shell.overlay', function* () {\n        yield ctx.slots.register({ name: 'shell.overlay', id: 'pet', order: 1000 }, () => h(PetMulti, {}));\n      });\n\n      // 设置页「桌宠配置」：大小、位置、模型，保存即时生效。\n      // useRef 供「AI 模型」下拉的浮层定位与外部点击判定使用。\n      const PetConfigSection = makePetConfigSection({ h, useState, useEffect, useRef, useCallback, t }, ctx);\n      ctx.slots.inject('settings.section', function* () {\n        yield ctx.slots.register(\n          { name: 'settings.section', id: 'pet-config', order: 30, label: () => t('nav'), inject: () => ({ t }) },\n          PetConfigSection,\n        );\n      });\n\n      // 快捷键独立注册：不挂在侧栏注册里——侧栏服务缺失时侧栏没了，快捷键不该跟着没。\n      // 三条命令共用 app-shortcut 的注册壳，任何一条失败都只丢它自己。\n      let sidebarChatReady = false;\n      ctx.effect(() => {\n        const sidebarChat = registerPetChatShortcut(\n          ctx,\n          () => t('shortcut.open'),\n          () => openPetChatTab(ctx),\n        );\n        sidebarChatReady = sidebarChat.registered;\n        const card = registerPetCardShortcuts(ctx, (key) => t(key));\n        return () => {\n          sidebarChatReady = false;\n          sidebarChat.dispose();\n          card.dispose();\n        };\n      }, 'dsh-pet: shortcuts');\n\n      // 右侧栏「桌宠对话」：可选能力，服务缺失时只告警，不影响其它部位。\n      // 确认弹窗用平台原语（primitives 缺失时面板内部退化为内联确认条）。\n      // 整体再兜一层：任何注册异常都不许拖垮插件激活（否则整个 Web 端进不去）。\n      ctx.effect(() => {\n        try {\n          return registerPetChatTab(\n            ctx,\n            {\n              h,\n              useEffect,\n              useRef,\n              useState,\n              ...(primitives === undefined\n                ? {}\n                : {\n                    ui: {\n                      Modal: primitives.Modal,\n                      Button: primitives.Button,\n                      ImageLightbox: primitives.ImageLightbox,\n                    },\n                  }),\n            },\n            // 命令没登记成功就不带 commandId：指向不存在的命令会让侧栏注册抛错\n            sidebarChatReady ? { commandId: PET_CHAT_COMMAND_ID } : {},\n          );\n        } catch (error) {\n          console.error('[dsh-pet] 右侧栏对话面板注册失败（已忽略，不影响启动）：', error);\n          return () => {};\n        }\n      }, 'dsh-pet: sidebar chat tab');\n    }\n\n    module.exports = { apply, inject, name };\n    return module.exports;\n  };\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/session-watch.ts",
      "content": "/**\n * 会话事件监听：把 DSH 的 session/event 折叠成工作状态与完成通知。\n *\n * 不决定通知文案与档位（归 notify-events 与 shared/work-status），只做事件到判定的转接。\n * @module dsh-pet/src/host/plugin/session-watch\n */\nimport { GOAL_UPDATE_TOOL, currentTaskFromTodo, goalUpdateAction, reduceWorkStatus } from '../work-status.ts';\nimport { toolDetailFromEvent } from '../tool-detail.ts';\nimport {\n  agentErrorFrame,\n  lastAssistantText,\n  isCompletionTurnEnd,\n  reduceNotifyFrame,\n  sessionIdOf,\n  shouldNotifySession,\n  withSessionId,\n} from '../notify-events.ts';\nimport type { SessionNotify, ToolCallKey, ToolCallLedger } from './session-notify.ts';\nimport type { WorkStatusBridge } from './work-status-bridge.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 会话事件监听的输入。 */\nexport type SessionWatchInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<SessionNotify, 'cancelTerminalCleanup'> &\n  Pick<SessionNotify, 'lastTodoText'> &\n  Pick<SessionNotify, 'lastReplyText'> &\n  Pick<SessionNotify, 'notifyActivityTimers'> &\n  Pick<WorkStatusBridge, 'publishWorkStatus'> &\n  Pick<SessionNotify, 'pushNotifyFrame'> &\n  Pick<SessionNotify, 'scheduleCompletionNotify'> &\n  Pick<SessionNotify, 'scheduleTerminalCleanup'> &\n  Pick<SessionNotify, 'terminalTimers'> &\n  Pick<SessionNotify, 'toolsInFlight'> &\n  Pick<SessionNotify, 'turnFlags'> &\n  Pick<HostSetup, 'workStatus'>;\n\n/** 一次工具事件在记账表里的形态：调用开始（带详情）或结果返回（按标识移除一条）。 */\ntype ToolPhase =\n  | { kind: 'call'; detail: string; callId: ToolCallKey | undefined }\n  | { kind: 'result'; callId: ToolCallKey | undefined };\n\n/** 记账之后气泡的去向。 */\ntype ToolPhaseOutcome = {\n  /** 要写进气泡的文案；`undefined` = 本次不改文案，`null` = 清空回落到档位文案。 */\n  task?: string | null;\n  /** 是否还有带描述的操作在跑：为真时把档位压回 working，避免结果档盖住没干完的活。 */\n  keepWorking: boolean;\n};\n\n/** 记账所需的一次工具事件输入。 */\ntype TrackInput = {\n  /** 事件类型，只有 `tool/call` 与 `tool/result` 会进记账表。 */\n  type: string;\n  /** 本次事件的调用标识；缺失时由记账层用临时 Symbol 占位。 */\n  callId: ToolCallKey | undefined;\n  /** `tool/call` 的详情文案；`null` 表示这次调用没有可展示的描述。 */\n  detail: string | null;\n  /** 该会话最近一条 todo 文案，表清空后回落到它。 */\n  lastTodo: string | null;\n};\n\n/**\n * 取本次工具事件的调用标识。\n *\n * `tool/call` 的标识在 `data.callId`，`tool/result` 在 `data.message.source.callId`\n * （`ToolResultMessage.source` 由 `ToolMessageSource` 保证必带）。\n *\n * @returns 非空字符串标识；缺失或类型不对时 `undefined`，交给记账层用临时 Symbol 占位。\n */\nfunction toolCallIdOf(event: unknown): ToolCallKey | undefined {\n  const data = (event as { data?: { callId?: unknown; message?: { source?: { callId?: unknown } } } } | null)?.data;\n  const raw = data?.message?.source?.callId ?? data?.callId;\n  return typeof raw === 'string' && raw !== '' ? raw : undefined;\n}\n\n/**\n * 更新一个会话的在途调用表，算出气泡该显示什么。\n *\n * @param ledger - 每会话在途调用表；本函数原地修改。\n * @param sessionId - 会话标识。\n * @param phase - 本次是调用开始还是结果返回，以及对应的调用标识。\n * @param lastTodo - 表清空后回落到的 todo 文案。\n * @returns 气泡文案与是否仍在工作。\n */\nfunction trackToolPhase(\n  ledger: ToolCallLedger,\n  sessionId: string,\n  phase: ToolPhase,\n  lastTodo: string | null,\n): ToolPhaseOutcome {\n  if (phase.kind === 'call') {\n    let pending = ledger.get(sessionId);\n    if (!pending) ledger.set(sessionId, (pending = new Map()));\n    pending.set(phase.callId ?? Symbol(), phase.detail);\n    return { task: phase.detail, keepWorking: true };\n  }\n  const pending = ledger.get(sessionId);\n  // 缺标识的结果只释放一个匿名条目：不猜它是哪个具名调用，宁可少记一条也不删错别人的。\n  const key = phase.callId ?? [...(pending?.keys() ?? [])].find((id) => typeof id === 'symbol');\n  if (key !== undefined) pending?.delete(key);\n  const remaining = [...(pending?.values() ?? [])];\n  if (pending?.size === 0) ledger.delete(sessionId);\n  const active = remaining.pop();\n  if (active !== undefined) return { task: active, keepWorking: true };\n  return { task: lastTodo, keepWorking: false };\n}\n\n/**\n * 把一次工具事件落进记账表。\n *\n * @param ledger - 每会话在途调用表；本函数原地修改。\n * @param sessionId - 会话标识。\n * @param input - 事件类型、调用标识与详情文案。\n * @returns 记账结果；没有可展示详情且不是结果事件时返回 `undefined`（气泡不因它改文案）。\n */\nfunction trackToolEvent(ledger: ToolCallLedger, sessionId: string, input: TrackInput): ToolPhaseOutcome | undefined {\n  if (input.detail !== null) {\n    return trackToolPhase(\n      ledger,\n      sessionId,\n      { kind: 'call', detail: input.detail, callId: input.callId },\n      input.lastTodo,\n    );\n  }\n  if (input.type === 'tool/result') {\n    return trackToolPhase(ledger, sessionId, { kind: 'result', callId: input.callId }, input.lastTodo);\n  }\n  return undefined;\n}\n\n/** 注册会话事件监听；返回的清理函数由 ctx.effect 收集。 */\nexport function registerSessionWatch(deps: SessionWatchInput): void {\n  const {\n    ctx,\n    cancelTerminalCleanup,\n    lastTodoText,\n    lastReplyText,\n    notifyActivityTimers,\n    publishWorkStatus,\n    pushNotifyFrame,\n    scheduleCompletionNotify,\n    scheduleTerminalCleanup,\n    terminalTimers,\n    toolsInFlight,\n    turnFlags,\n    workStatus,\n  } = deps;\n  // 工作状态联动：监听 DSH 会话事件 → 聚合当前活动状态（WorkStatusStore → 展示快照）。\n  // 消费 turn/start、user/message（goal 续跑轮判定）、tool/call、tool/result、approval/asked、\n  // turn/end、todo/write（只更新任务详情文案，不切档位）。纯监听不调用模型。\n  ctx.effect(() => {\n    const dispose = ctx.on('session/event', (session: unknown, event: unknown) => {\n      const type = (event as { type?: string } | null)?.type;\n      if (!type) return;\n      const sessionId = String(\n        (session as { id?: unknown; header?: { id?: unknown } } | null)?.header?.id ??\n          (session as { id?: unknown } | null)?.id ??\n          'unknown',\n      );\n      if (type === 'todo/write') {\n        // 任务详情文案只写该会话的条目（state/task 同源，不可能串会话）。会话没有活动条目\n        // （已空闲/已清理）→ 不动：不会被展示，写进去只会成为一条幽灵文案。\n        // 清单里再无 in_progress/pending 时返回 null，气泡回落到档位文案。\n        const text = currentTaskFromTodo(event as { data?: { todos?: Array<{ status?: string; content?: string }> } });\n        // 缓存无条件更新：工具跑完要靠它把气泡恢复回来（见下方 tool/call 的接线）\n        lastTodoText.set(sessionId, text);\n        // 工具正在执行时不覆盖气泡：「修改 index.ts」比清单里那句更能说明此刻在动什么\n        if ((toolsInFlight.get(sessionId)?.size ?? 0) > 0) return;\n        if (workStatus.has(sessionId)) {\n          workStatus.setTask(sessionId, text);\n          publishWorkStatus(); // 任务文案变化也要写 S（气泡内容靠它更新）\n        }\n        return;\n      }\n      if (type === 'user/message') {\n        // 目标续跑轮判定：自动轮的消息带 source.kind==='goal'（round>0），该轮属自动续跑，\n        // 其 turn/end completed 只是「本轮完成」，不是整个任务完成\n        const source = (event as { data?: { source?: { kind?: string } } })?.data?.source;\n        if (source?.kind === 'goal') {\n          const flags = turnFlags.get(sessionId) ?? { goalRound: false, closing: null };\n          flags.goalRound = true;\n          turnFlags.set(sessionId, flags);\n        }\n        return; // user/message 不驱动档位动画\n      }\n      if (type === 'turn/start') {\n        turnFlags.set(sessionId, { goalRound: false, closing: null }); // 新一轮：清 turn 级标志\n        // 新一轮也开始新的任务上下文：清掉上一轮留下的任务详情文案（issue #59），否则它会一直挂着。\n        // 代价：goal 续跑这类多轮任务，每轮开头会回落一瞬档位文案，直到本轮（通常在开头几步内）\n        // 再写一次 todo 清单。\n        workStatus.setTask(sessionId, null);\n        lastTodoText.delete(sessionId); // 上一轮的清单文案，不该被下一轮的工具跑完时「恢复」回来\n        toolsInFlight.delete(sessionId); // 上一轮若有工具没等到 tool/result（被打断），别拖累这一轮\n        publishWorkStatus(); // 清掉上一轮任务文案也要写 S\n      }\n      if (\n        type === 'tool/call' &&\n        String((event as { data?: { name?: unknown } })?.data?.name ?? '') === GOAL_UPDATE_TOOL\n      ) {\n        // update_goal complete/blocked = 本轮是该目标的收尾轮，其 completed 才是真完成\n        const action = goalUpdateAction(String((event as { data?: { arguments?: unknown } })?.data?.arguments ?? ''));\n        if (action) {\n          const flags = turnFlags.get(sessionId) ?? { goalRound: false, closing: null };\n          flags.closing = action;\n          turnFlags.set(sessionId, flags);\n        }\n      }\n      let next = reduceWorkStatus(\n        event as { type?: string; data?: Record<string, unknown> & { reason?: { kind?: string } } },\n        turnFlags.get(sessionId),\n      );\n      if (!next) {\n        // turn/end 的 null（aborted / 未知 kind）＝该会话回合已结束：清掉会话状态，让展示回到空闲或\n        // 落到其他活跃会话，防止回合被打断后永久卡在上一档；其他事件的 null 是「不关心」，忽略。\n        if (type === 'turn/end') {\n          turnFlags.delete(sessionId);\n          cancelTerminalCleanup(sessionId); // 条目都要清了，别留一个到点后无事可做的定时器\n          lastTodoText.delete(sessionId); // 按会话记的两份缓存跟着会话一起消失（防泄漏）\n          toolsInFlight.delete(sessionId);\n          workStatus.clear(sessionId); // 条目连同任务详情文案一起消失（clear 内部会重算展示）\n          publishWorkStatus(); // 回合被打断 → 回到空闲：前端据此收起常驻气泡\n        }\n        return;\n      }\n      const seq = Number((event as { seq?: unknown }).seq ?? 0);\n      // 工具详情（「修改 index.ts」这类具体描述）：比通用档位文案有用得多，workStatusEnabled\n      // 的宠物直接把它当气泡文本。\n      // 必须在 setState 之后写：setTask 要求会话条目已存在，而条目正是 setState 建出来的——\n      // 顺序反了这一句会被静默丢弃（不报错，最难查的那种）。\n      const detail =\n        type === 'tool/call' ? toolDetailFromEvent(event as { data?: { name?: unknown; arguments?: unknown } }) : null;\n      const outcome = trackToolEvent(toolsInFlight, sessionId, {\n        type,\n        callId: toolCallIdOf(event),\n        detail,\n        lastTodo: lastTodoText.get(sessionId) ?? null,\n      });\n      // 还有操作没完就把档位压回 working：结果档与「仍在执行」的文案同时出现会自相矛盾。\n      if (outcome?.keepWorking) next = 'working';\n      const changed = workStatus.setState(sessionId, next, seq);\n      if (outcome?.task !== undefined) workStatus.setTask(sessionId, outcome.task);\n      publishWorkStatus(); // 档位或文案变了 → 写 S（内容没变时它自己会短路，不产生多余写入）\n      // 同会话同状态不重复更新（防刷屏）：写已经落定，这里只负责跳过终态清理的重排\n      if (!changed) return;\n      // 终态只展示短暂窗口后自动清理：陈旧完成态不再浮上来（Bug 3 的一环，顺带缓解 Bug 2 残留）。\n      // 回到非终态则取消那次待执行的清理——否则它到点时会话已非终态，既不清也不重排，\n      // 条目（连同旧任务文案）就永久留下了。\n      if (next === 'success' || next === 'error') scheduleTerminalCleanup(sessionId);\n      else cancelTerminalCleanup(sessionId);\n    });\n    return () => {\n      dispose();\n      for (const t of terminalTimers.values()) clearTimeout(t);\n      terminalTimers.clear();\n    };\n  }, 'dsh-pet: work-status session events');\n\n  // 系统通知：监听 DSH 宿主事件生成通知帧入队，浏览器轮询 /state 读到后弹 toast（帧契约与\n  // shared/notify.ts 一致）。事件源：turn/end、approval/asked、tool/call（ask_user_question）、\n  // agent/error。两道门：会话门（子代理/委派不发）+ 活动门（只拦「对话完成」，延迟确认没活了再弹）。\n  // 纯监听不调用模型；通知是网页端能力，桌面模式不消费。\n  ctx.effect(() => {\n    const sessionDispose = ctx.on(\n      'session/event',\n      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- session/event 载荷无公开类型，any 只用于接收，函数内立刻交给 shouldNotifySession / reduceNotifyFrame 推导\n      (session: any, event: any) => {\n        // 会话门（issue #82）：子代理 / 委派会话不发通知——你等的是父对话，不是某一路子代理跑完。\n        // 判据用 header.origin（不是 parentSession，那会把普通 fork 的主对话一起静音），\n        // 判据不可用时放行，绝不把通知整体打哑。详见 notify-events.ts 的 shouldNotifySession。\n        if (!shouldNotifySession(session)) return;\n        // 回复正文来源：只记最近一段 assistant 文本，供完成通知的正文使用。取不到就不记，\n        // 下游回落空正文（宁可少一行字，也不能让通知整体失效）。\n        if (event?.type === 'assistant/message') {\n          const text = lastAssistantText(event as { type?: string; data?: Record<string, unknown> });\n          if (text) lastReplyText.set(sessionIdOf(session), text);\n        }\n        // 活动门（issue #114）：「对话完成」延迟确认这条会话确实没活了再弹——团队会话里 Lead 的\n        // 这一轮结束 ≠ 团队收工，成员还在跑时弹「对话完成」是误报。生成失败/输出截断、权限申请、\n        // 用户选择不过这道门，直接放行（理由见 notify-events.ts 的 isCompletionTurnEnd）。\n        if (isCompletionTurnEnd(event)) {\n          scheduleCompletionNotify(sessionIdOf(session), event);\n          return;\n        }\n        // 非完成收尾（出错 / 输出截断 / 中止）用不到这段正文，一并清掉，免得留到下一次完成。\n        if (event?.type === 'turn/end') lastReplyText.delete(sessionIdOf(session));\n        const frame = reduceNotifyFrame(event as Parameters<typeof reduceNotifyFrame>[0]);\n        // 帧带上「这条通知是哪条会话发出的」：点击时网页据此跳到那条会话（见 withSessionId）\n        if (frame) pushNotifyFrame(withSessionId(frame, sessionIdOf(session)));\n      },\n    );\n    // agent/error（agent-loop dispatch.emit）：无回合位置的生成失败；0.1.5 新增，\n    // 低版本 DSH 无此事件 = 少一条通知（turn/end error 分支已覆盖大部分失败场景），不报错。\n    // 两道门都管不到它：载荷只有 { turn, step, error }，不带会话标识，无从判定来源。\n    const errorDispose = ctx.on(\n      'agent/error',\n      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- agent/error 载荷无公开类型，且低版本 DSH 可能不带 error 字段，只能 any 后按可选链取 payload?.error\n      (payload: any) => {\n        pushNotifyFrame(agentErrorFrame(payload?.error));\n      },\n    );\n    return () => {\n      // 卸载时清掉待查的定时器：否则插件已卸载，到点还去写一次 S\n      for (const t of notifyActivityTimers.values()) clearTimeout(t);\n      notifyActivityTimers.clear();\n      sessionDispose();\n      errorDispose();\n    };\n  }, 'dsh-pet: notify frames');\n}\n"
    },
    {
      "path": "dsh-pet/src/host/work-status.ts",
      "content": "/**\n * 工作状态联动（host 半侧，自包含，不 import src/shared）。\n *\n * 负责监听 DSH 的 session/event，把会话事件压缩成「当前活动工作状态」并按会话聚合，\n * 由调用方写进 sections.workStatus，两端轮询 /state 后按 counter 变化渲染。\n * 只做聚合与去重：状态无变化不产生新输出（签名比对防刷屏），不调用任何模型。\n * 依赖会话事件与调用方维护的 turn 上下文；不负责档位文案与动画，那些在两端消费侧。\n * 始终成立：档位顺序与 animations.events.workStatus 数组索引严格一致，不在中间插入。\n * 契约见 API.md 与 openapi.yaml。\n *\n * @module dsh-pet/src/host/work-status\n */\n\n/** 工作状态档位（数组索引 = events.workStatus 档位；顺序与 shared/work-status.ts 一致）。 */\nexport const HOST_WORK_STATUS_STATES = ['thinking', 'working', 'result', 'waiting', 'success', 'error'] as const;\nexport type HostWorkStatusState = (typeof HOST_WORK_STATUS_STATES)[number];\n\n/**\n * 回合结束原因 → 档位：completed → success，错误系（error / max-tokens / timeout）→ error，\n * blocked → waiting；其余（aborted 等）→ null，由调用方清理会话回空闲——残留上一档会让回合被\n * 打断后永远卡在 working。\n */\nfunction turnEndState(kind: string): HostWorkStatusState | null {\n  if (kind === 'completed') return 'success';\n  if (kind === 'error' || kind === 'max-tokens' || kind === 'timeout') return 'error';\n  if (kind === 'blocked') return 'waiting';\n  return null;\n}\n\n/** ask_user_question 工具名：模型在等用户选择题答复 → 归为 waiting（等待确认）而非普通工作。 */\nconst USER_QUESTION_TOOL = 'ask_user_question';\n\n/** update_goal 工具名：目标工具，action=complete/blocked = 本轮是该目标任务的收尾轮。 */\nexport const GOAL_UPDATE_TOOL = 'update_goal';\n\n/** 本 turn 的 turn 级标志（goal 续跑轮判定；不参与展示，由调用方维护）。 */\nexport interface WorkStatusTurnContext {\n  /** 本轮是否为自动目标续跑轮（user/message source.kind==='goal' 时置位，turn/start 清零）。 */\n  goalRound?: boolean;\n  /** 本轮是否调用过 update_goal 收尾（'complete' | 'blocked'；undefined/null = 未收尾）。 */\n  closing?: 'complete' | 'blocked' | null;\n}\n\n/** 解析 update_goal 的 arguments（原始 JSON 字符串）→ 收尾动作；解析失败 / 非收尾动作返回 null。 */\nexport function goalUpdateAction(args: string): 'complete' | 'blocked' | null {\n  try {\n    const o = JSON.parse(args) as { action?: unknown } | null;\n    const action = String(o?.action ?? '');\n    if (action === 'complete' || action === 'blocked') return action;\n  } catch {\n    /* 非法 JSON：按未收尾处理 */\n  }\n  return null;\n}\n\n/**\n * turn/end completed 的终局判定：非 goal 轮直接 success；自动续跑轮的中间轮 → result（本轮完成\n * 不等于整个任务完成，不庆祝）；收尾轮 complete → success，blocked → error（目标被阻塞结束，\n * 诚实地表沮丧而非庆祝）。\n */\nexport function completedState(turn: WorkStatusTurnContext | undefined): HostWorkStatusState {\n  if (!turn?.goalRound) return 'success';\n  if (turn.closing === 'blocked') return 'error';\n  if (turn.closing === 'complete') return 'success';\n  return 'result';\n}\n\n/** 从会话事件压缩出工作状态；无变化 / 不关心返回 null。\n *  turn 为当前回合上下文（goal 续跑轮判定），只影响 turn/end completed 的终局语义。 */\nexport function reduceWorkStatus(\n  event: {\n    type?: string;\n    data?: Record<string, unknown> & { reason?: { kind?: string } };\n  },\n  turn?: WorkStatusTurnContext,\n): HostWorkStatusState | null {\n  switch (event?.type) {\n    case 'turn/start':\n      return 'thinking';\n    case 'tool/call': {\n      // 问用户问题的工具（选择题弹窗）＝ 等用户答复，不是普通干活\n      if (String(event?.data?.name ?? '') === USER_QUESTION_TOOL) return 'waiting';\n      return 'working';\n    }\n    case 'tool/result':\n      return 'result';\n    case 'approval/asked':\n      return 'waiting';\n    case 'turn/end': {\n      // completed→success、错误系→error、blocked→waiting；其余（aborted 等）→null＝清该会话回空闲\n      const reason = turnEndState(String(event?.data?.reason?.kind ?? ''));\n      // 本轮完成是否等于整个任务完成交给 completedState（goal 续跑轮的中间轮不庆祝）\n      if (reason === 'success') return completedState(turn);\n      return reason;\n    }\n    default:\n      return null; // todo/write 等：不切动画（详情文案由调用方另行处理）\n  }\n}\n\n/**\n * 任务详情文案长度上限（按码点计，超出截断加省略号）：气泡最大宽度只有 0.5×宠物宽\n * （默认 size 462 时约 231px，字号 21px 约一行 11 个汉字），而清单原文动辄几十字，不截断会把\n * 气泡撑成好几行、盖住宠物。截断放在 host 这一处，两端天然一致。\n */\nexport const TASK_TEXT_MAX = 40;\n\n/**\n * todo/write 的 in_progress/pending 项文本 → 任务详情；null = 清单已全部完成。\n *\n * 取最后一个 in_progress 而不是第一个：agent 常把新步骤标成 in_progress 却忘了把上一步标\n * completed，取第一个会永远停在最早那步。没有进行中的项时回落到第一个 pending（下一步要做的）。\n */\nexport function currentTaskFromTodo(event: {\n  data?: { todos?: Array<{ status?: string; content?: string }> };\n}): string | null {\n  const todos = Array.isArray(event?.data?.todos) ? event.data.todos : [];\n  let current: { status?: string; content?: string } | undefined;\n  for (const t of todos) {\n    if (t?.status === 'in_progress') current = t;\n  }\n  if (!current) current = todos.find((t) => t?.status === 'pending');\n  const content = String(current?.content ?? '').trim();\n  if (!content) return null;\n  // 按码点切，避免把代理对（emoji 等）截成半个字符\n  const points = Array.from(content);\n  return points.length > TASK_TEXT_MAX ? `${points.slice(0, TASK_TEXT_MAX).join('')}…` : content;\n}\n\n/** 工作状态快照（/work-status 端点响应体）：state 为主状态；task 为 todo 详情（可 null）。 */\nexport interface WorkStatusSnapshot {\n  state: HostWorkStatusState | null; // null = 尚无会话活动（空闲）\n  task: string | null; // 当前任务详情（todo/write 提供，可 null）\n  ts: number; // 最近一次变化的时间戳（轮询侧据此检测变化）\n}\n\n/** 每会话聚合条目。 */\nexport interface SessionWorkEntry {\n  /** 该会话当前档位。 */\n  state: HostWorkStatusState;\n  /** 该会话最近事件的序号，同档位时按它取最近。 */\n  seq: number;\n  /** 任务详情文案；null = 该会话没有清单。 */\n  task: string | null;\n}\n\n/** 展示优先级：waiting > error > working > thinking > result > success。\n *  result 高于 success：任何会话的进行中过渡态都不被别处已完成态压过，防中途庆祝；同档按最近更新优先。 */\nexport const WORK_STATUS_PRIORITY: Record<HostWorkStatusState, number> = {\n  waiting: 60,\n  error: 50,\n  working: 40,\n  thinking: 30,\n  result: 25,\n  success: 20,\n};\n\n/** 展示用条目：所有会话里优先级最高者（同优先级取 seq 更大者）；无会话返回 undefined。 */\nexport function pickDisplayed(entries: Iterable<SessionWorkEntry>): SessionWorkEntry | undefined {\n  let best: SessionWorkEntry | undefined;\n  for (const entry of entries) {\n    if (\n      !best ||\n      WORK_STATUS_PRIORITY[entry.state] > WORK_STATUS_PRIORITY[best.state] ||\n      (WORK_STATUS_PRIORITY[entry.state] === WORK_STATUS_PRIORITY[best.state] && entry.seq > best.seq)\n    ) {\n      best = entry;\n    }\n  }\n  return best;\n}\n\n/**\n * 工作状态聚合（纯逻辑，可单测）：按会话维护 state / task，对外只暴露一个展示快照。\n *\n * task 必须挂在会话条目上：挂成全局单值就没有独立于 todo/write 的生命周期，写过一次会跟着此后\n * 所有会话活动一直显示，连配置里的 workStatusTexts 档位文案也被永久屏蔽。挂进条目后文案与它的\n * 会话同生共死：条目被清、新一轮 turn/start、清单里再无进行中项，文案都会消失。\n * 展示时 state 与 task 取自同一个 best 会话，因此不会出现 A 会话的状态配 B 会话的文案。\n */\nexport class WorkStatusStore {\n  // 类字段一律 declare + 构造器赋值：带初始化器的类字段在 target es2020 下要被降级，\n  // 降级产物会 import 未声明的 @oxc-project/runtime helper——宿主加载插件树时直接\n  // ERR_MODULE_NOT_FOUND，整个 profile 起不来（scripts/prepack-check.js 第 8 项守着这条）。\n  declare private readonly sessions: Map<string, SessionWorkEntry>;\n  declare private readonly snap: WorkStatusSnapshot;\n\n  constructor() {\n    this.sessions = new Map();\n    this.snap = { state: null, task: null, ts: 0 };\n  }\n\n  /** 该会话当前是否有活动条目（决定 todo/write 是否还值得更新它的文案）。 */\n  has(sessionId: string): boolean {\n    return this.sessions.has(sessionId);\n  }\n\n  /** 该会话当前档位（无条目 / 已清返回 undefined）。 */\n  stateOf(sessionId: string): HostWorkStatusState | undefined {\n    return this.sessions.get(sessionId)?.state;\n  }\n\n  /** 该会话当前任务详情（无条目返回 null）。 */\n  taskOf(sessionId: string): string | null {\n    return this.sessions.get(sessionId)?.task ?? null;\n  }\n\n  /** 写会话状态（保留该会话已有的 task）；同状态且 seq 不更新则不写并返回 false（防刷屏）。 */\n  setState(sessionId: string, state: HostWorkStatusState, seq = 0): boolean {\n    const prev = this.sessions.get(sessionId);\n    if (prev?.state === state && prev.seq >= seq) return false;\n    this.sessions.set(sessionId, { state, seq, task: prev?.task ?? null });\n    this.refresh();\n    return true;\n  }\n\n  /** 写该会话的任务详情（null = 清空）；会话无活动条目 → 不动（它不会被展示）。 */\n  setTask(sessionId: string, task: string | null): boolean {\n    const prev = this.sessions.get(sessionId);\n    if (!prev || prev.task === task) return false;\n    this.sessions.set(sessionId, { ...prev, task });\n    this.refresh();\n    return true;\n  }\n\n  /** 清掉某会话（回合结束 / 终态过期）：它的 task 一并消失，不会残留到后续活动里。 */\n  clear(sessionId: string): boolean {\n    if (!this.sessions.delete(sessionId)) return false;\n    this.refresh();\n    return true;\n  }\n\n  /** 展示快照（对象引用稳定，供 /work-status 直接序列化）。 */\n  snapshot(): WorkStatusSnapshot {\n    return this.snap;\n  }\n\n  /** 重算展示：state 与 task 任一变化才更新 ts（轮询侧据此触发，两端都靠它刷新）。 */\n  private refresh(): void {\n    const best = pickDisplayed(this.sessions.values());\n    const nextState = best?.state ?? null;\n    const nextTask = best?.task ?? null;\n    if (nextState === this.snap.state && nextTask === this.snap.task) return;\n    this.snap.state = nextState;\n    this.snap.task = nextTask;\n    this.snap.ts = Date.now();\n  }\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/work-status-bridge.ts",
      "content": "/**\n * 工作状态联动：把 store 里的活动状态按 5s 间隔压扁后写进轮询快照。\n *\n * 不监听会话事件（归会话监听器），不渲染气泡。\n * 依赖由 apply 显式传入（见输入类型），模块内不读全局、不建单例。\n * @module dsh-pet/src/host/plugin/work-status-bridge\n */\nimport type { HostSetup } from './setup.ts';\n\n/** 工作状态桥的输入：装配期对象与更早的工厂。 */\nexport type WorkStatusBridgeInput = {} & Pick<HostSetup, 'state'> & Pick<HostSetup, 'workStatus'>;\n\n/**\n * 创建工作状态桥。\n */\nexport function createWorkStatusBridge(deps: WorkStatusBridgeInput) {\n  const { state, workStatus } = deps;\n  // 工作状态快照写进 S：内容真的变了才写（每次写都推进 counter，前端据此重播档位动画）。\n  // 只压「距上次写入不足 WORK_STATE_GAP_MS 的 working → result」——工具秒回时会来回切十几次，\n  // 每切一次前端就把片段从第 0 帧重播；反向不压（开工迟到比多换一次片更糟），终态不压。\n  const WORK_STATE_GAP_MS = 5000;\n\n  let publishedWork = '\\u0000';\n\n  let publishedState: string | null = null;\n\n  let publishedWorkAt = 0;\n\n  let workFlushTimer: ReturnType<typeof setTimeout> | null = null;\n\n  const publishWorkStatus = (): void => {\n    const snap = workStatus.snapshot();\n    const key = String(snap.state) + '\\u0000' + String(snap.task);\n    if (key === publishedWork) return;\n    // 抖动判定：只压 working → result 这一个方向（同档只换文案不算抖动，照常立即写；\n    // 反向 result → working 立即写）\n    const busyFlip = publishedState === 'working' && snap.state === 'result';\n    const wait = WORK_STATE_GAP_MS - (Date.now() - publishedWorkAt);\n    if (busyFlip && wait > 0) {\n      // 整条不写（档位与文案一起压住）：到点再取最新快照补写\n      // （不要在这里缓存 snap——期间可能又变了）\n      workFlushTimer ??= setTimeout(() => {\n        workFlushTimer = null;\n        publishWorkStatus();\n      }, wait);\n      return;\n    }\n    if (workFlushTimer !== null) {\n      clearTimeout(workFlushTimer);\n      workFlushTimer = null;\n    }\n    publishedWork = key;\n    publishedState = snap.state;\n    publishedWorkAt = Date.now();\n    state.writeSection('workStatus', { state: snap.state, task: snap.task });\n  };\n\n  /** 停掉挂起的补写定时器（插件卸载时调用）。 */\n  const stopWorkStatusFlush = (): void => {\n    if (workFlushTimer !== null) {\n      clearTimeout(workFlushTimer);\n      workFlushTimer = null;\n    }\n  };\n  return { publishWorkStatus, stopWorkStatusFlush };\n}\n/** 工作状态桥的产出（供下游工厂按需 Pick）。 */\nexport type WorkStatusBridge = ReturnType<typeof createWorkStatusBridge>;\n"
    },
    {
      "path": "dsh-pet/src/client/pet/multi.ts",
      "content": "/**\n * 多开容器：拉一次成品配置、长轮询 /state 叶子，再把指令分发给对应的宠物卡。\n * 只做「配置 → 渲染列表」与「叶子 → 每只宠物」的分发，不解释叶子语义、不画 DOM。\n * 必须始终成立：首拉只记基线，之后 counter 变化才分发；配置形状异常时显式报错，绝不用空列表清空。\n * @module dsh-pet/src/client/pet/multi\n */\nimport type { FunctionComponent, ReactNode } from 'react';\nimport { petBridge } from '../settings/bridge.ts';\nimport { flattenConfigPets, isWebVisible } from '../../shared/config.ts';\nimport { decideBalanceNotice } from '../../shared/balance/index.ts';\nimport { ROUTE_PATH } from '../../shared/constants.ts';\nimport { readMenuItems } from '../../shared/menu.ts';\nimport {\n  fetchState,\n  flattenCounters,\n  readAnim,\n  readBalance,\n  readLock,\n  readPosition,\n  readSay,\n  readSleep,\n  readThrow,\n  readWorkStatus,\n  resolveLeafPath,\n  takeChanged,\n} from '../../shared/state.ts';\nimport { fontStackOf } from '../../shared/fonts.ts';\nimport type { Pet } from '../../shared/types.ts';\nimport type { BalanceState } from '../../shared/balance/index.ts';\nimport type {\n  LockState,\n  PetFacing,\n  PetLeafName,\n  PollState,\n  PositionMode,\n  SayCue,\n  SectionLeafName,\n  SleepState,\n  StateLeaf,\n} from '../../shared/state.ts';\nimport type { MenuMoreItem } from '../../shared/menu.ts';\nimport type { PetCollisionSlot } from '../../shared/physics.ts';\nimport type { WorkStatusSnapshot } from '../../shared/work-status.ts';\nimport type { PetCardProps } from './card/props.ts';\nimport type { PetRuntime, RuntimePet } from './types.ts';\nimport { setClickSoundEnabled } from './click-sound.ts';\nimport { setSurface, setVoiceConfig } from '../../shared/voice.ts';\nimport { runStatePoll } from './state-poll.ts';\nimport { setMenuItems } from '../menu-service.ts';\nimport { setStateSnapshot } from '../state-service.ts';\nimport { notifyFromFrame } from '../notify.ts';\nimport { STATE_FALLBACK_MS, STATE_WAIT_MS } from './timings.ts';\n\n/**\n * 造多开容器。\n *\n * @param rt - 注入的 react 能力。\n * @param Card - 单只宠物的卡片组件。\n * @returns 容器组件。\n */\nexport function createPetMulti(\n  rt: Pick<PetRuntime, 'h' | 'useState' | 'useEffect' | 'useRef'>,\n  Card: FunctionComponent<PetCardProps>,\n): () => ReactNode {\n  const { h, useState, useEffect, useRef } = rt;\n\n  return function PetMulti() {\n    const [pets, setPets] = useState<Pet[]>([]);\n    const [ready, setReady] = useState(false);\n    // 碰撞站场：每只 PetCard 注册槽位，纯 ref 同步，不触发重渲染。\n    const arenaRef = useRef<{ slots: Record<string, PetCollisionSlot> }>({ slots: {} });\n    // 余额状态：容器统一拉取，PetCard 共享；两个 tick 分别驱动动画与文字说明。\n    const [balance, setBalance] = useState<BalanceState | null>(null);\n    const [balanceTick, setBalanceTick] = useState(0);\n    const [balanceNoticeTick, setBalanceNoticeTick] = useState(0);\n    // 本次余额是否由用户手动请求；手动请求无条件弹，开关只关自动。\n    const [balanceManual, setBalanceManual] = useState(false);\n    // 上次已提示的不可用原因，自动轮询只在原因变化时再弹。\n    const noticeKeyRef = useRef<string | null>(null);\n    // 余额结果统一入口；存 ref 是为了让 /state effect 的依赖保持 [ready]。\n    // explicit 表示本次是否手动触发。\n    const applyBalanceRef = useRef<(state: BalanceState, explicit: boolean) => void>(() => {});\n    applyBalanceRef.current = (state, explicit) => {\n      setBalance(state);\n      setBalanceManual(explicit); // 手动标记随本次数据一起下发，每次到达都覆盖。\n      if (state.ok) {\n        setBalanceTick((t) => t + 1); // 成功：播档位动画并弹余额气泡。\n        return;\n      }\n      const { show, key } = decideBalanceNotice(state, noticeKeyRef.current, explicit);\n      noticeKeyRef.current = key;\n      if (show) setBalanceNoticeTick((t) => t + 1); // 弹文字说明气泡（不播动画）\n      // 未登记服务商是配置事实，已由气泡说明；其余原因照旧显式报错。\n      if (state.reason !== 'unsupported') {\n        console.error('[dsh-pet] 余额查询失败 reason=' + state.reason + (state.message ? ' ' + state.message : ''));\n      }\n    };\n    // 工作状态：容器统一轮询 sections.workStatus，快照与 tick 驱动各宠物播档位动画。\n    const [workStatus, setWorkStatus] = useState<WorkStatusSnapshot | null>(null);\n    const [workStatusTick, setWorkStatusTick] = useState(0);\n    // 说话：容器把 pets.<id>.say 按宠物分发给对应 PetCard。\n\n    // 字体族写到 documentElement：对话窗与得分弹窗挂在 body 下，继承不到宠物根容器。\n    useEffect(() => {\n      const family = pets[0]?.font?.family;\n      if (family === undefined) return;\n      document.documentElement.style.setProperty('--dsh-pet-font-family', fontStackOf(family));\n    }, [pets]);\n\n    useEffect(() => {\n      let alive = true;\n      /** 唯一填充点：成品聚合 → 渲染列表；条目级字段只由 flattenConfigPets 吹入。 */\n      const applyMerged = (merged: Record<string, Record<string, unknown>>): void => {\n        const main = (merged as { main?: Record<string, unknown> } | null)?.main;\n        // 形状校验：响应异常时显式抛错，绝不用空列表清空已有宠物。\n        if (typeof main !== 'object' || main === null) {\n          throw new Error('配置响应不是成品聚合（host 版本不匹配？）');\n        }\n        // 点击音效开关只读 main 条目，非 true 一律静音。\n        setClickSoundEnabled(main.clickSoundEnabled === true);\n        // 本页就是网页端：按叶子播放时只认 voiceTo='web' 的那一句。\n        setSurface('web');\n        // 音色、总开关与音量同源：缺字段即「不播」，不在端上兜默认值。\n        setVoiceConfig(main.voiceName, main.voiceEnabled, main.voiceVolume);\n        const flattened = flattenConfigPets(merged);\n        petBridge.current = flattened;\n        // 「添加宠物」模板取 main 条目的 pets[0]。\n        petBridge.template = Array.isArray(main.pets) ? ((main.pets as Pet[])[0] ?? undefined) : undefined;\n        setPets(flattened);\n      };\n      /** 拉取成品聚合：host readAllConfig 的输出，客户端零校验零兜底。 */\n      const loadMerged = async (): Promise<Record<string, Record<string, unknown>>> => {\n        // cache:'no-store' 与 fetchState 同口径，避免「版本变化后重拉」拿到旧值。\n        const r = await fetch(ROUTE_PATH + '/config', { cache: 'no-store' });\n        if (!r.ok) throw new Error('config HTTP ' + r.status);\n        const body = (await r.json()) as Record<string, unknown>;\n        // 业务失败也是 200：ok:false 的体不是成品配置，别拿它去拍平（会静默退化成默认配置）\n        if (body.ok === false) throw new Error('config: ' + String(body.reason ?? 'failed'));\n        return body as Record<string, Record<string, unknown>>;\n      };\n      (async () => {\n        try {\n          const merged = await loadMerged();\n          if (!alive) return;\n          applyMerged(merged);\n          setReady(true);\n        } catch (e) {\n          console.error('[dsh-pet] 配置加载失败', e); // 成品拉取失败要显式报错，不静默隐藏。\n        }\n      })();\n      // 设置页保存或同步后，用权威成品重新拍平；传入 merged 时直接用写接口的响应体。\n      petBridge.reload = (merged) => {\n        void (async () => {\n          try {\n            const next = merged ?? (await loadMerged());\n            if (!alive) return;\n            applyMerged(next);\n          } catch (e) {\n            console.error('[dsh-pet] 配置重载失败，保留当前渲染列表', e); // 显式报错，不清空已有宠物。\n          }\n        })();\n      };\n      return () => {\n        alive = false;\n        petBridge.reload = () => {};\n      };\n    }, []);\n\n    // overlay 只渲染 display 为 web 或 both 的宠物。\n    const visiblePets = pets.filter((p) => isWebVisible(p.display));\n\n    // 统一轮询 /state：每个叶子 = { counter, data }，首拉只记基线，之后 counter 变化才分发。\n    // 说话等命令与宠物开关无关，所以不为功能开关裁剪轮询。\n    const [sayTick, setSayTick] = useState(0);\n    const sayRef = useRef<Record<string, SayCue & { seq: number }>>({});\n    const [animCueTick, setAnimCueTick] = useState(0);\n    const animCueRef = useRef<\n      Record<string, { name?: string; url?: string; seq: number; playbackId?: string; facing?: PetFacing }>\n    >({});\n    const [posCueTick, setPosCueTick] = useState(0);\n    const posCueRef = useRef<\n      Record<string, { x: number; y: number; mode: PositionMode; duration: number; seq: number }>\n    >({});\n    const [throwCueTick, setThrowCueTick] = useState(0);\n    const throwCueRef = useRef<Record<string, { angle: number; power: number; seq: number }>>({});\n    // 占用锁是状态而不是指令：PetCard 读它决定冻结，并按 expiresAt 自行解除。\n    const [lockTick, setLockTick] = useState(0);\n    const lockRef = useRef<Record<string, LockState>>({});\n    // 睡觉同样是状态：三段名字由宿主挑定，卡片据此播开始→循环→起来。\n    const [sleepTick, setSleepTick] = useState(0);\n    const sleepRef = useRef<Record<string, SleepState>>({});\n    // 第三方菜单项只在打开右键菜单时读一次，不参与渲染。\n    const menuItemsRef = useRef<MenuMoreItem[]>([]);\n    useEffect(() => {\n      if (!ready) return;\n      let alive = true;\n      let baseline: Record<string, number> | null = null;\n      /** 分段叶子 → 消费端副作用；不认识的名字已被 resolveLeafPath 挡在外面。 */\n      const applySection = (name: SectionLeafName, leaf: StateLeaf): void => {\n        switch (name) {\n          case 'config':\n            // 配置被别处改过（唯一写方是 POST /pet-display），重新拉取并拍平。\n            // 叶子 data 只是信号，配置本体太大，不能塞进 /state。\n            petBridge.reload();\n            return;\n          case 'balance': {\n            const hit = readBalance(leaf);\n            if (hit) applyBalanceRef.current(hit.state, hit.manual);\n            return;\n          }\n          case 'workStatus': {\n            const snap = readWorkStatus(leaf);\n            if (snap) {\n              setWorkStatus(snap);\n              setWorkStatusTick((t) => t + 1); // 任何变化都触发，含回到空闲。\n            }\n            return;\n          }\n          case 'notify':\n            // 系统通知：单槽，由 host 决定保留哪一条，内部有开关与权限门。\n            notifyFromFrame(leaf.data);\n            return;\n          case 'menu':\n            // 第三方菜单快照只更新 ref，不触发渲染；同一份交给页面内菜单镜像，供 petApi7340.menuEvents 读取。\n            menuItemsRef.current = readMenuItems(leaf.data, 'web');\n            setMenuItems(menuItemsRef.current);\n            return;\n        }\n      };\n\n      /** 宠物叶子 → 该宠物的指令槽；序号自增，卡片据此知道「又写了一次」。 */\n      const applyPetLeaf = (name: PetLeafName, petId: string, leaf: StateLeaf): void => {\n        switch (name) {\n          case 'say': {\n            const said = readSay(leaf);\n            if (!said) return;\n            sayRef.current[petId] = { ...said, seq: (sayRef.current[petId]?.seq ?? 0) + 1 };\n            setSayTick((t) => t + 1);\n            return;\n          }\n          case 'anim': {\n            // 每次写入都会递增 counter，连点两次也会分发两次。\n            const hit = readAnim(leaf);\n            if (!hit) return;\n            animCueRef.current[petId] = {\n              name: hit.name,\n              url: hit.url,\n              playbackId: hit.playbackId,\n              facing: hit.facing,\n              seq: (animCueRef.current[petId]?.seq ?? 0) + 1,\n            };\n            setAnimCueTick((t) => t + 1);\n            return;\n          }\n          case 'position': {\n            const hit = readPosition(leaf);\n            if (!hit) return;\n            posCueRef.current[petId] = { ...hit, seq: (posCueRef.current[petId]?.seq ?? 0) + 1 };\n            setPosCueTick((t) => t + 1);\n            return;\n          }\n          case 'throw': {\n            const hit = readThrow(leaf);\n            if (!hit) return;\n            throwCueRef.current[petId] = { ...hit, seq: (throwCueRef.current[petId]?.seq ?? 0) + 1 };\n            setThrowCueTick((t) => t + 1);\n            return;\n          }\n          case 'lock': {\n            // 占用锁是状态而不是指令：卡片按 expiresAt 自行解除。\n            const hit = readLock(leaf);\n            if (!hit) return;\n            lockRef.current[petId] = hit;\n            setLockTick((t) => t + 1);\n            return;\n          }\n          case 'sleep': {\n            // 睡觉也是状态：卡片按三段名字播「开始→循环→起来」，醒来后回随机链。\n            const hit = readSleep(leaf);\n            if (!hit) return;\n            sleepRef.current[petId] = hit;\n            setSleepTick((t) => t + 1);\n            return;\n          }\n        }\n      };\n\n      /** 应用一份轮询状态：首拉只记基线，之后按 counter 变化逐个分发。 */\n      const applyState = (s: PollState) => {\n        // 最近一拍先留给同页消费者（petApi7340.getState）：它读的是同一个对象，不占连接。\n        setStateSnapshot(s);\n        if (baseline === null) {\n          baseline = flattenCounters(s); // 首拉只记基线，不渲染。\n          // 菜单项是当前状态而不是事件，首拉也必须装上，否则刷新后第三方菜单会一直为空。\n          menuItemsRef.current = readMenuItems(s.sections.menu?.data, 'web');\n          setMenuItems(menuItemsRef.current);\n          // 睡觉同样是状态而不是事件：刷新页面时宿主仍记着它在睡，首拉必须补一次；\n          // 否则页面显示醒着，而宿主对「已在睡」不回写叶子，只能等宿主重启才恢复。\n          for (const [petId, entry] of Object.entries(s.pets)) {\n            const hit = entry?.sleep?.data == null ? null : readSleep(entry.sleep);\n            if (hit) sleepRef.current[petId] = hit;\n          }\n          setSleepTick((t) => t + 1);\n          return;\n        }\n        for (const { path, leaf } of takeChanged(s, baseline)) {\n          if (leaf.data === null) continue;\n          const target = resolveLeafPath(path);\n          // 不认识的路径（新增的叶子、别处写坏的键）静默跳过。\n          if (target === null) continue;\n          if (target.where === 'section') applySection(target.name, leaf);\n          else applyPetLeaf(target.name, target.petId, leaf);\n        }\n      };\n      // 自调度轮询在 pet/state-poll.ts：这里只提供拉取与分发。\n      void runStatePoll({\n        fetch: (options) =>\n          fetchState(\n            undefined,\n            options === undefined ? undefined : { since: options.since, timeoutMs: options.timeoutMs },\n          ),\n        onState: applyState,\n        waitMs: STATE_WAIT_MS,\n        fallbackMs: STATE_FALLBACK_MS,\n        isAlive: () => alive,\n      });\n      return () => {\n        alive = false;\n      };\n    }, [ready]);\n\n    return ready\n      ? visiblePets.map((p) =>\n          h(Card, {\n            key: p.id,\n            cfg: p as RuntimePet,\n            balance,\n            balanceTick,\n            balanceNoticeTick,\n            balanceManual,\n            workStatus,\n            workStatusTick,\n            say: sayRef.current[p.id],\n            sayTick,\n            animCue: animCueRef.current[p.id],\n            animCueTick,\n            posCue: posCueRef.current[p.id],\n            posCueTick,\n            throwCue: throwCueRef.current[p.id],\n            throwCueTick,\n            lock: lockRef.current[p.id],\n            lockTick,\n            sleep: sleepRef.current[p.id],\n            sleepTick,\n            menuItemsRef,\n            arena: arenaRef,\n          }),\n        )\n      : null;\n  };\n}\n"
    },
    {
      "path": "dsh-pet/src/client/pet/state-poll.ts",
      "content": "/**\n * `/state` 的自调度轮询：请求 → 分发 → 立刻再请求，宿主没变化时挂起。\n * 首拍用无 since 的普通请求探出宿主是否支持长轮询（`counter` 存在即支持），之后带上 since 挂起等待。\n * 失败或老宿主退避一个间隔，避免变成忙等；卸载由 `isAlive` 判断，循环自行退出。\n * @module dsh-pet/src/client/pet/state-poll\n */\nimport type { PollState } from '../../shared/state.ts';\n\n/** 轮询器依赖。 */\nexport interface StatePollDeps {\n  /** 拉一次状态；`timeoutMs` 已按宿主能力决定，`undefined` 表示普通请求。 */\n  fetch: (options?: { since: number; timeoutMs: number }) => Promise<PollState | null>;\n  /** 拿到有效快照后分发叶子。 */\n  onState: (state: PollState) => void;\n  /** 长轮询的挂起时长（ms）。 */\n  waitMs: number;\n  /** 失败或老宿主时的退避间隔（ms）。 */\n  fallbackMs: number;\n  /** 组件是否仍然挂载；false 时循环立刻退出。 */\n  isAlive: () => boolean;\n}\n\n/** 一个不会 resolve 的等待：单纯让出这一拍，用定时器而不是忙等。 */\nconst sleep = (ms: number): Promise<void> => new Promise((resolve) => setTimeout(resolve, ms));\n\n/**\n * 启动自调度轮询（调用方不 await：它一直跑到 `isAlive()` 返回 false）。\n *\n * @param deps - 拉取、分发与节奏参数。\n * @returns 无返回值；循环结束后自然收尾。\n */\nexport async function runStatePoll(deps: StatePollDeps): Promise<void> {\n  /** 宿主是否支持长轮询：首拍带 counter 就是支持。 */\n  let longPoll = false;\n  /** 上次拿到的 counter，作为长轮询的 since。 */\n  let since: number | undefined;\n  while (deps.isAlive()) {\n    let state: PollState | null = null;\n    try {\n      state = await deps.fetch(longPoll && since !== undefined ? { since, timeoutMs: deps.waitMs } : undefined);\n    } catch {\n      /* 轻量轮询失败静默，下一拍再试。 */\n    }\n    if (!deps.isAlive()) return;\n    if (state !== null) {\n      longPoll = typeof state.counter === 'number';\n      if (longPoll && typeof state.counter === 'number') since = state.counter;\n      deps.onState(state);\n    }\n    // 长轮询命中或首拉时立刻再请求；失败或老宿主则退避一个间隔。\n    if (state === null || !longPoll) await sleep(deps.fallbackMs);\n  }\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/http-route.ts",
      "content": "/**\n * 路由装配：把装配期对象收成 PetRouteDeps，接上领域路由，并把处理函数挂到 webServer。\n *\n * 路由层只认这个 deps 表，不认识 apply 的闭包；素材路径与协议细节归 ../http.ts。\n * 必须始终成立：HTTP 前缀路由与桌面 Helper 管道消费同一个 handlePetRoute（两端行为严格一致）。\n * @module dsh-pet/src/host/plugin/http-route\n */\nimport type { IncomingMessage, ServerResponse } from 'node:http';\nimport { ROUTE_SEGMENT } from '../../shared/constants.ts';\nimport { readBody, sendFile, sendJson, sendText, type RouteResult } from '../http.ts';\nimport { failureBody } from '../routes/result.ts';\nimport { createPetRouter } from '../routes/index.ts';\nimport type { PetRouteDeps } from '../routes/types.ts';\nimport type { HostContext } from './context.ts';\n\n/** 单次业务请求的处理函数：URL 已解析、方法已归一。 */\nexport type HttpRouteHandler = (\n  url: string,\n  method: string,\n  body?: string,\n  signal?: AbortSignal,\n) => Promise<RouteResult>;\n\n/**\n * 由依赖表构造 HTTP 处理函数。\n * @param deps - 路由层依赖（store、路径、动作函数）。\n * @returns 按前缀分发到领域路由的处理函数。\n */\nexport function createHttpRoute(deps: PetRouteDeps): { handlePetRoute: HttpRouteHandler } {\n  // 配置请求覆盖完整读改写：下一次更新必须读取前一次完成后的配置。\n  // GET /config 同样排队，避免写入尚未完成时读到空文件而回退内置默认。\n  let configQueue: Promise<void> = Promise.resolve();\n\n  /** 单次业务路由（HTTP 落盘与桌面 Helper 管道共用同一份实现）：输入 rawUrl + method + body 文本，\n   *  返回 RouteResult，消费方各自落盘——业务逻辑只有一份，两端天然一致。\n   *  signal 可选：调用方断开时中止挂起等待（只有 /playback 的 wait 分支会用到；管道侧不传）。 */\n  const handlePetRoute = async (\n    rawUrl: string,\n    method: string,\n    body?: string,\n    signal?: AbortSignal,\n  ): Promise<RouteResult> => {\n    const url = new URL(rawUrl, 'http://localhost');\n    const rest = decodeURIComponent(url.pathname.slice(ROUTE_SEGMENT.length + 1));\n    const run = (): Promise<RouteResult> => dispatchPetRoute(url, rest, method, body, signal);\n    // 写配置的三条路径（PUT/POST /config、POST /pet-display、POST /pet-config）都是「读当前配置\n    // → 白名单重建整段 pets → 写盘」，并发交错会互相覆盖，必须共用一条串行队列；\n    // GET /config 同样排队，避免写入尚未完成时读到空文件而回退内置默认。\n    const isConfigQueue = rest === 'config' || ((rest === 'pet-display' || rest === 'pet-config') && method === 'POST');\n    if (isConfigQueue) {\n      const pending = configQueue.then(run, run);\n      configQueue = pending.then(\n        () => undefined,\n        () => undefined,\n      );\n      return pending;\n    }\n    return run();\n  };\n\n  // 路由层依赖表：显式传参取代闭包捕获，各领域模块因此可独立演进（见 ./routes/index.ts）\n  const dispatchPetRoute = createPetRouter(deps);\n\n  return { handlePetRoute };\n}\n\n/**\n * 把前缀路由挂到宿主 webServer，随插件卸载自动摘除。\n * @param ctx - 宿主上下文。\n * @param handlePetRoute - 业务处理函数（桌面 Helper 管道复用同一个）。\n */\nexport function registerHttpRoute(ctx: HostContext, handlePetRoute: HttpRouteHandler): void {\n  ctx.effect(\n    () =>\n      ctx.webServer.register({\n        kind: 'prefix',\n        path: ROUTE_SEGMENT,\n        handler: async (req: IncomingMessage, res: ServerResponse) => {\n          // 挂起等待（/playback?wait=）期间调用方可能提前断开：据此中止等待，\n          // 否则那个等待者要一直留到超时才回收。'close' 在正常应答后也会触发，但那时监听已摘掉。\n          const abort = new AbortController();\n          const onClose = (): void => abort.abort();\n          res.on('close', onClose);\n          try {\n            // PATCH 也带体（待办的部分更新）；GET / DELETE 不读，避免无谓地等一个不会来的结束事件。\n            const readsBody = req.method === 'PUT' || req.method === 'POST' || req.method === 'PATCH';\n            const body = readsBody ? await readBody(req) : undefined;\n            const result = await handlePetRoute(req.url ?? '/', req.method ?? 'GET', body, abort.signal);\n            res.off('close', onClose);\n            if (result.kind === 'json') sendJson(res, result.status, result.obj, result.headers);\n            else if (result.kind === 'text') sendText(res, result.status, result.body);\n            else if (result.kind === 'none') {\n              /* 调用方已断开：不再写（写了会抛） */\n            } else sendFile(req, res, result.file, result.contentType); // 非 async：流在 open 后自己 pipe，错误内部收口\n          } catch (e) {\n            res.off('close', onClose);\n            // 连接已断（挂起等待被中止后也可能撞上）→ 不再写，避免二次抛错\n            if (!res.destroyed && !res.writableEnded) {\n              // 请求体超限与客户端中断是用户侧问题，不能报成 500；断连时连响应都写不出去。\n              const code = (e as { code?: string }).code;\n              if (code === 'body-too-large')\n                sendJson(res, 413, failureBody('payload-too-large', 'request body too large'));\n              else if (code !== 'client-aborted') {\n                // 未预期异常：真实原因只进日志，响应里只回分类文案（可能含绝对路径，不外泄）\n                ctx.logger?.warn?.(`[dsh-pet] route failed: ${e instanceof Error ? e.message : String(e)}`);\n                sendJson(res, 500, failureBody('internal-error', 'dsh-pet: internal error'));\n              }\n            }\n          }\n        },\n      }),\n    `dsh-pet: ${ROUTE_SEGMENT} asset route`,\n  );\n}\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/desktop/spawn.ts",
      "content": "/**\n * Helper 进程的拉起与停止：定位 Electron、注入环境、退避重试与熔断。\n *\n * 不算宠物列表（归 ./pets），不决定何时重启（归 ./sync 的调用方）。\n * 依赖显式传入（见输入类型），模块内只读两个进程级环境事实：`DSH_PET_IN_PROCESS` 与 `process.versions.electron`。\n * @module dsh-pet/src/host/plugin/desktop/spawn\n */\nimport { join } from 'node:path';\nimport { ROUTE_SEGMENT } from '../../../shared/constants.ts';\nimport { PACKAGE_ROOT } from '../../paths.ts';\nimport type { DesktopHelperDeps } from './types.ts';\nimport type { DesktopPets } from './pets.ts';\nimport { toBridgeResponse } from './bridge-response.ts';\nimport {\n  HelperProcess,\n  defaultElectronExe,\n  dshHomeDir,\n  ensureElectronDownload,\n  hasGraphicalDisplay,\n  resolveElectronPath,\n} from '../../helper-process.ts';\n\n/** DesktopSpawn的输入。 */\nexport type DesktopSpawnInput = Pick<\n  DesktopHelperDeps,\n  'ctx' | 'getHandlePetRoute' | 'log' | 'reportDownload' | 'thumbUserRoot'\n> &\n  Pick<DesktopPets, 'getHasDesktopPet' | 'desktopPetList' | 'getTrayOn'>;\n\n/** 宿主是不是 DSH 桌面应用（Electron 宿主）。 */\nconst isDesktopHost = (): boolean => Boolean(process.versions.electron);\n\n/** 菜单首项去向：desktop 唤起桌面应用，standalone 打开本机 AI 设置页，web 打开 DSH 站点。 */\nexport type OpenTarget = 'desktop' | 'standalone' | 'web';\n\n/**\n * 由宿主形态与已鉴权地址判定菜单首项去向。\n *\n * 独立模式与 web 宿主都不在 Electron 里，只能靠地址形状区分：独立模式的已鉴权地址固定落在本机\n * 设置页，web 宿主指向站点根。判错会让菜单文案与实际打开的目标对不上。\n * @param siteUrl - 交给浏览器的已鉴权地址（独立模式含本机设置页路径）。\n * @param desktopHost - 宿主是否为 DSH 桌面应用。\n * @returns 注入给 Helper 的形态值。\n */\nexport function resolveOpenTarget(siteUrl: string, desktopHost: boolean): OpenTarget {\n  if (desktopHost) return 'desktop';\n  return siteUrl.includes('/standalone-ai/') ? 'standalone' : 'web';\n}\n\n/**\n * 创建 Helper 进程的拉起与停止句柄：进程内宿主直接跳过，其余按需下载 Electron 后 spawn 并退避重试。\n */\nexport function createDesktopSpawn(deps: DesktopSpawnInput) {\n  const { ctx, getHandlePetRoute, log, reportDownload, thumbUserRoot, getHasDesktopPet, desktopPetList, getTrayOn } =\n    deps;\n\n  let desktopModeEverActive = false;\n\n  let helper: HelperProcess | undefined;\n\n  let startRetryTimer: NodeJS.Timeout | undefined;\n\n  let electronEnsure: Promise<void> | undefined;\n\n  let disposed = false;\n\n  let displayWarned = false;\n\n  let noDesktopSkipped = false;\n\n  let portWaitAttempts = 0;\n\n  const inProcessHost = process.env.DSH_PET_IN_PROCESS === '1';\n\n  const launchHelper = (electronPath: string | undefined): void => {\n    if (inProcessHost) return; // 应用模式：窗口由本进程建，绝不 spawn\n    if (helper || disposed) return;\n    // 无桌面宠物时：只有「桌面模式曾启用过且托盘还开着」才值得为托盘常驻，否则不启动\n    if (!getHasDesktopPet() && !(desktopModeEverActive && getTrayOn())) return;\n    const port = typeof ctx.webServer?.port === 'number' ? ctx.webServer.port : 0;\n    if (!port || port <= 0) {\n      // webServer 可能尚未完成监听（OS 分配端口时 port 短暂为 0）：延迟重试。\n      // 诊断日志（issue #168）：这条重试以前完全静默——端口长期不就绪时，桌面宠物\n      // 「连尝试都没有」且没有任何线索。这里只加可见性，重试节奏与次数保持原样。\n      portWaitAttempts += 1;\n      if (portWaitAttempts === 1) {\n        log.info(`[dsh-pet] webServer 端口尚未就绪（port=${String(port)}），每 500ms 重试拉起桌面 Helper`);\n      } else if (portWaitAttempts % 20 === 0) {\n        log.warn(\n          `[dsh-pet] 已等待 webServer 端口 ${(portWaitAttempts * 500) / 1000}s 仍未就绪` +\n            `（port=${String(port)}），桌面 Helper 尚未拉起`,\n        );\n      }\n      if (!startRetryTimer) {\n        startRetryTimer = setTimeout(() => {\n          startRetryTimer = undefined;\n          launchHelper(electronPath);\n        }, 500);\n        startRetryTimer.unref?.();\n      }\n      return;\n    }\n    portWaitAttempts = 0;\n    // 用宿主自报的监听地址，不写死 loopback：DSH 拒绝通配地址，host 永远是某块具体网卡——只绑 LAN IP\n    // 时 127.0.0.1 并不监听，写死会让右键「打开网站」打开一个连不上的页面。getOrigin() 在绑定地址\n    // 无法表达成 URL（带 zone 的 IPv6）时抛，此时退回 loopback：菜单打不开，但不拖垮 Helper 拉起。\n    let origin = `http://127.0.0.1:${port}`;\n    try {\n      origin = ctx.webServer.getOrigin();\n    } catch {\n      /* 见上：保留 loopback 兜底 */\n    }\n    // 右键「打开网站」交出去的是裸 origin：DSH 只在 `GET /` 接受本进程的启动令牌，换发绑定该 authority\n    // 的签名 Cookie，其余请求一律 401，故传 origin 而不是另拼地址。令牌等价登录态：只经子进程环境变量\n    // 递到 helper 内存，不落盘、不进日志。\n    const siteUrl = ctx.connection.authenticatedUrl(origin);\n    // 桌面渲染端也从同一份 handlePetRoute 拿成品配置（每只宠物一个局部小窗口；经管道，不走 HTTP——\n    // DSH Desktop 2.0.3+ 会拦插件自拉进程的裸 HTTP 请求，浏览器访问闸门只放行带令牌的请求）\n    const configUrl = `${origin}${ROUTE_SEGMENT}/config`;\n    helper = new HelperProcess(\n      {\n        electronPath,\n        env: {\n          DSH_PET_CONFIG_URL: configUrl,\n          // 已鉴权站点 URL（含本进程启动令牌）：只供 helper 的「打开」首项使用，任何日志都不许出现它\n          DSH_PET_SITE_URL: siteUrl,\n          // 宿主形态决定菜单首项的去向与文案（同名「打开」项，三种形态三种语义）：\n          //   desktop    = DSH 桌面应用 → 唤起应用主窗口（helper 走 dsh://open）\n          //   standalone = 独立模式 → 本机 AI 设置页\n          //   web        = dsh web → DSH 站点\n          DSH_PET_OPEN_TARGET: resolveOpenTarget(siteUrl, isDesktopHost()),\n          DSH_PET_SCALE: '1',\n          // 打开 bridge 协议：main.js 注册 dsh-pet-bridge scheme，把渲染端请求经管道转给宿主\n          DSH_PET_BRIDGE: '1',\n          // 每只桌面宠物一个局部小窗口：透传宠物列表（[{id,size}]）\n          DSH_PET_PETS: JSON.stringify(desktopPetList()),\n        },\n        // bridge 协议处理器 = HTTP 路由同一份 handlePetRoute（业务逻辑唯一，两端天然一致）；\n        // 形状转换在 ./bridge-response，本模块只管把请求转进去。\n        bridgeHandler: async (req) => {\n          const result = await getHandlePetRoute()(req.url ?? '/', req.method ?? 'GET', req.body);\n          return toBridgeResponse(req.id, result);\n        },\n      },\n      log,\n    );\n    try {\n      helper.start();\n      desktopModeEverActive = true; // 此后即使桌面宠物清零也保留 Helper：托盘常驻，可随时切回来\n      log.info(`dsh-pet desktop helper started (config: ${configUrl})`);\n    } catch (e) {\n      log.warn(`dsh-pet desktop helper start failed: ${e instanceof Error ? e.message : String(e)}`);\n      helper = undefined;\n    }\n  };\n\n  const startHelper = (): void => {\n    if (inProcessHost) return; // 应用模式：不探测、不下载 Electron\n    if (helper || electronEnsure || disposed) return;\n    if (!getHasDesktopPet() && !(desktopModeEverActive && getTrayOn())) {\n      // 诊断日志（issue #168）：这条短路不打日志，就是「桌面模式凭空消失：无进程、无目录、无提示」\n      // 的直接成因。用 info 而非 warn——纯网页用户这是正常状态；只打一次避免刷屏。\n      // 托盘关掉后这里也会命中：没人需要那个图标，空常驻没有意义。\n      if (!noDesktopSkipped) {\n        noDesktopSkipped = true;\n        log.info(\n          `[dsh-pet] 无桌面宠物（display 均为 web/none）且无需保留托盘（tray=${getTrayOn()}），已跳过桌面 Helper 启动`,\n        );\n      }\n      return;\n    }\n    // 无图形显示环境（Linux 服务器 / 容器）：直接放弃，不探测、不下载、不拉起。\n    // 否则 Electron 会「拉起即崩」，被守护循环反复重启并刷满 core dump。\n    if (!hasGraphicalDisplay()) {\n      if (!displayWarned) {\n        displayWarned = true;\n        log.warn(\n          '[dsh-pet] 未检测到图形显示环境（DISPLAY/WAYLAND_DISPLAY 均为空），已跳过桌面宠物。' +\n            '浏览器内宠物不受影响；如需在服务器上启用桌面模式，请配置 Xvfb 后设置 DSH_PET_DESKTOP_FORCE=1。',\n        );\n      }\n      return;\n    }\n    const found = resolveElectronPath();\n    if (found) {\n      launchHelper(found);\n      return;\n    }\n    // 诊断日志（issue #168）：只报「没找到」不够用——最常见的情形是「文件明明存在」，\n    // 但不在实际查询的路径上（DSH_HOME 不一致）。把真正查的路径一起打出来。\n    log.warn(\n      `[dsh-pet] 未找到 Electron 可执行文件：DSH_HOME=${dshHomeDir()}，查找路径=${defaultElectronExe()}` +\n        `，DSH_PET_ELECTRON_PATH=${process.env.DSH_PET_ELECTRON_PATH ?? '(未设置)'}`,\n    );\n    log.warn(`[dsh-pet] 开始下载 Electron 到 ${defaultElectronExe()} ...`);\n    electronEnsure = ensureElectronDownload({\n      // 下载全过程写进工作状态气泡（用户没有控制台，只能靠它看进度与失败原因）\n      onLog: ({ text, level, done }) =>\n        reportDownload(text, level === 'warn' ? 'error' : done ? 'success' : 'working', done),\n      // 同一份进度也落盘：气泡只在有宠物显示时可见，桌面版 Helper 起不来时它就没有载体\n      logger: log,\n    })\n      .then((path) => {\n        if (path) {\n          launchHelper(path);\n        } else {\n          log.warn(\n            '[dsh-pet] Electron download failed; desktop pet unavailable. Set DSH_PET_ELECTRON_PATH and restart, or retry later.',\n          );\n        }\n      })\n      .finally(() => {\n        electronEnsure = undefined;\n      });\n  };\n\n  const stopHelper = (reason = 'settings-change'): void => {\n    if (startRetryTimer) {\n      clearTimeout(startRetryTimer);\n      startRetryTimer = undefined;\n    }\n    helper?.stop(reason);\n    helper = undefined;\n  };\n\n  const stopHelperAndWait = async (reason: string): Promise<void> => {\n    if (startRetryTimer) {\n      clearTimeout(startRetryTimer);\n      startRetryTimer = undefined;\n    }\n    const old = helper;\n    helper = undefined;\n    await old?.stopAndWait(reason);\n  };\n\n  const animSubdirFor = (ext: string): string => (ext === '.mov' ? 'mov' : 'webm');\n\n  const assetRootFor = (ext: string): string => join(PACKAGE_ROOT, 'assets', animSubdirFor(ext));\n\n  const userRootFor = (ext: string): string => join(thumbUserRoot, animSubdirFor(ext));\n\n  const markDisposed = (): void => {\n    disposed = true;\n  };\n\n  return { startHelper, stopHelper, stopHelperAndWait, markDisposed, assetRootFor, userRootFor };\n}\n\n/** DesktopSpawn的产出。 */\nexport type DesktopSpawn = ReturnType<typeof createDesktopSpawn>;\n"
    },
    {
      "path": "dsh-pet/src/host/plugin/lifecycle.ts",
      "content": "/**\n * 卸载清理：摘监听、停定时器、结束挂起等待，顺序不可调换。\n *\n * 不做启动（装配末尾单独 startHelper），不持有资源句柄。\n * @module dsh-pet/src/host/plugin/lifecycle\n */\nimport type { PetLookup } from './pet-lookup.ts';\nimport type { DesktopHelper } from './desktop-helper.ts';\nimport type { DownloadReport } from './download-report.ts';\nimport type { WorkStatusBridge } from './work-status-bridge.ts';\nimport type { HostSetup } from './setup.ts';\nimport type { HostContext } from './context.ts';\n\n/** 卸载清理的输入。 */\nexport type LifecycleInput = {\n  /** 宿主上下文（apply 收到的那一个）。 */\n  ctx: HostContext;\n} & Pick<PetLookup, 'lock'> &\n  Pick<DesktopHelper, 'markDisposed'> &\n  Pick<HostSetup, 'playback'> &\n  Pick<HostSetup, 'state'> &\n  Pick<DownloadReport, 'stopDownloadSlotTimer'> &\n  Pick<DesktopHelper, 'stopHelper'> &\n  Pick<WorkStatusBridge, 'stopWorkStatusFlush'>;\n\n/** 注册卸载清理；返回的清理函数由 ctx.effect 收集。 */\nexport function registerLifecycle(deps: LifecycleInput): void {\n  const { ctx, lock, markDisposed, playback, state, stopDownloadSlotTimer, stopHelper, stopWorkStatusFlush } = deps;\n  // 随插件生命周期清理：桌面 Helper 回收（异步下载完成后不再拉起）+ 结束所有挂起的等待\n  // （回执与 /state 长轮询不结束的话，插件重载会留下一批悬挂响应，各自要等到超时才收尾）。\n  ctx.effect(() => () => {\n    markDisposed();\n    // 工作状态的补写定时器：卸载后它到点已经没有意义（叶子连同长轮询一起收尾），清掉免得挂着\n    stopWorkStatusFlush();\n    // 下载日志的「清槽」定时器：同上，卸载后它到点已经没有意义\n    stopDownloadSlotTimer();\n    // 占用锁：卸载时把锁全撤掉并写一次叶子——不写的话渲染端要等 TTL 到点才解除静止\n    // （写叶子必须在 state.cancelAll() 之前：那之后挂起的等待者已经收尾了）。\n    lock.releaseAll();\n    playback.cancelAll();\n    state.cancelAll();\n    stopHelper('dsh-host-stop');\n  });\n}\n"
    },
    {
      "path": "dsh-pet/src/standalone/request-security.ts",
      "content": "/**\n * 本机 HTTP 的访问边界：回环 Host 校验、CSRF 校验与进程能力令牌。\n *\n * 负责判定请求能否进入路由，并清掉上游写出的宽 CORS 头；不处理业务语义。\n * 必须始终成立：只接受当前回环地址；令牌只出现在启动清单与请求头，绝不进日志或响应。\n * @module dsh-pet/src/standalone/request-security\n */\nimport { randomBytes, timingSafeEqual } from 'node:crypto';\nimport type { IncomingMessage, ServerResponse } from 'node:http';\n\n/** 请求安全门面。 */\nexport interface RequestSecurity {\n  /** 进程能力令牌，只写入本机启动清单，绝不进 HTTP 响应或日志。 */\n  readonly token: string;\n  /** 生成带令牌的设置页地址。 */\n  authenticatedUrl(baseUrl: string): string;\n  /** 判定请求是否放行；拒绝时已经写好响应。 */\n  authorize(req: IncomingMessage, res: ServerResponse, allowFileOrigin?: boolean): boolean;\n}\n\n/** 回一个结构化错误并返回 false，便于调用方直接 return。 */\nexport function rejectRequest(res: ServerResponse, status: number, error: string): false {\n  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' });\n  res.end(JSON.stringify({ error }));\n  return false;\n}\n\n/** 无需令牌的只读路径；写操作与敏感路径必须带令牌。 */\nfunction publicRead(req: IncomingMessage): boolean {\n  // 插件在分发前会解码路径，鉴权必须用同一种拼写判断。\n  const path = decodeURIComponent(new URL(req.url ?? '/', 'http://127.0.0.1').pathname);\n  if (req.method !== 'GET' && req.method !== 'HEAD') return false;\n  if (['/standalone-ai/settings', '/shutdown'].includes(path)) return false;\n  if (/^\\/dsh-pet-\\d+\\/(?:whisper|chat)(?:\\/|$)/.test(path)) return false;\n  return (\n    ['/', '/health', '/standalone-ai/', '/standalone-ai/settings.js', '/standalone-ai/settings.css'].includes(path) ||\n    /^\\/dsh-pet-\\d+\\//.test(path)\n  );\n}\n\n/** 创建请求安全门面。 */\nexport function createRequestSecurity(): RequestSecurity {\n  const token = randomBytes(32).toString('base64url');\n  return {\n    token,\n    authenticatedUrl(baseUrl) {\n      const base = new URL(baseUrl);\n      if (\n        base.protocol !== 'http:' ||\n        !['127.0.0.1', 'localhost'].includes(base.hostname) ||\n        base.username ||\n        base.password\n      ) {\n        throw new Error('设置地址必须是本机 HTTP 地址');\n      }\n      return `${base.origin}/standalone-ai/#token=${token}`;\n    },\n    authorize(req, res, allowFileOrigin = false) {\n      const host = req.headers.host;\n      const port = req.socket.localPort;\n      if (!port || (host !== `127.0.0.1:${port}` && host !== `localhost:${port}`)) {\n        return rejectRequest(res, 403, '仅允许当前本机地址');\n      }\n      // 文件页渲染器也要带令牌：沙箱网页同样会发来 null 来源。\n      // 同一渲染器加载媒体时可能完全不带 Origin，只有这种情况才放行。\n      const fileOrigin = allowFileOrigin && (req.headers.origin === 'null' || req.headers.origin === undefined);\n      if (\n        !fileOrigin &&\n        ((req.headers.origin !== undefined && req.headers.origin !== `http://${host}`) ||\n          req.headers['sec-fetch-site'] === 'cross-site')\n      ) {\n        return rejectRequest(res, 403, '不允许跨站请求');\n      }\n      try {\n        if (publicRead(req) && !fileOrigin) return true;\n      } catch {\n        return rejectRequest(res, 400, '请求地址无效');\n      }\n      const supplied = req.headers['x-dsh-pet-token'];\n      // 先按固定形状校验，再走定时安全比较，避免长度与内容泄漏。\n      if (\n        typeof supplied !== 'string' ||\n        !/^[A-Za-z0-9_-]{43}$/.test(supplied) ||\n        !timingSafeEqual(Buffer.from(supplied), Buffer.from(token))\n      ) {\n        return rejectRequest(res, 403, '请从桌宠菜单重新打开设置');\n      }\n      return true;\n    },\n  };\n}\n\n/** 清掉上游写出的宽 CORS 头，并补上安全响应头。 */\nexport function secureResponse(res: ServerResponse, pathname?: string): void {\n  const writeHead = res.writeHead.bind(res);\n  const isPublicOp = pathname === '/' || pathname === '/health';\n  res.writeHead = ((status: number, ...args: unknown[]) => {\n    const filtered = isPublicOp\n      ? args\n      : args.map((value) => {\n          if (Array.isArray(value)) {\n            return value.reduce<string[]>((result, item, index) => {\n              if (index % 2 === 0 && !String(item).toLowerCase().startsWith('access-control-')) {\n                return [...result, String(item), String(value[index + 1])];\n              }\n              return result;\n            }, []);\n          }\n          if (value !== null && typeof value === 'object') {\n            return Object.fromEntries(\n              Object.entries(value).filter(([name]) => !name.toLowerCase().startsWith('access-control-')),\n            );\n          }\n          return value;\n        });\n    if (!isPublicOp) {\n      for (const name of res.getHeaderNames()) {\n        if (name.toLowerCase().startsWith('access-control-')) res.removeHeader(name);\n      }\n    }\n    res.setHeader('x-content-type-options', 'nosniff');\n    res.setHeader('referrer-policy', 'no-referrer');\n    res.setHeader('cache-control', 'no-store');\n    return Reflect.apply(writeHead, res, [status, ...filtered]);\n  }) as typeof res.writeHead;\n}\n"
    },
    {
      "path": "dsh-pet/src/host/routes/state.ts",
      "content": "/**\n * 轮询侧数据：/models 模型目录、/state 全局快照（支持 since/timeout 长轮询）、/work-status 工作状态写入。\n *\n * 不生成状态，只汇总 store 里的当前值。\n * 依赖（PetRouteDeps）显式传入，模块内不读全局、不建状态。\n * @module dsh-pet/src/host/routes/state\n */\nimport { parseStateWaitQuery } from '../state.ts';\nimport { type RouteResult } from '../http.ts';\nimport { HOST_WORK_STATUS_STATES, TASK_TEXT_MAX, type HostWorkStatusState } from '../work-status.ts';\nimport type { PetRouteDeps, RouteInput } from './types.ts';\nimport { failResult, invalidJson, methodNotAllowed, okResult, payloadTooLarge } from './result.ts';\n\n/** 轮询状态领域：未命中返回 undefined，命中返回应答。 */\nexport async function handleStateRoutes(deps: PetRouteDeps, input: RouteInput): Promise<RouteResult | undefined> {\n  const { EXTERNAL_WORK_SESSION, ctx, nextExternalWorkSeq, publishWorkStatus, state, workStatus } = deps;\n  const { body, method, rest, signal, url } = input;\n\n  // 可选模型清单（设置页「AI 模型」下拉框数据源）：与 DSH 模型选择器同源，都来自宿主 llm 服务。\n  // 只读、无副作用；某个服务商列模型失败（适配器不支持 / 网络）只让它空着，不拖垮整张清单。\n  // 一个实时路由都没注册时回落到 listConfigurableProviders，免得下拉框空着。\n  if (rest === 'models') {\n    if (method !== 'GET') return methodNotAllowed();\n    try {\n      const llm = ctx.llm as\n        | {\n            listProviders?: () => Array<{ id?: unknown; name?: unknown }>;\n            listConfigurableProviders?: () => Array<{ provider?: unknown; displayName?: unknown }>;\n            listModels?: (provider: string) => Promise<Array<{ id?: unknown; name?: unknown }>>;\n          }\n        | undefined;\n      const named = (id: unknown, name: unknown): { id: string; name: string } => {\n        const pid = String(id ?? '');\n        return { id: pid, name: String(name ?? '') || pid };\n      };\n      let providers = (typeof llm?.listProviders === 'function' ? llm.listProviders() : []).map((p) =>\n        named(p?.id, p?.name),\n      );\n      if (providers.length === 0 && typeof llm?.listConfigurableProviders === 'function') {\n        providers = llm.listConfigurableProviders().map((p) => named(p?.provider, p?.displayName));\n      }\n      providers = providers.filter((p) => p.id);\n      const catalog = await Promise.all(\n        providers.map(async (p) => {\n          let models: Array<{ id: string; name: string }> = [];\n          try {\n            const list = await llm?.listModels?.(p.id);\n            models = (Array.isArray(list) ? list : []).map((m) => named(m?.id, m?.name)).filter((m) => m.id);\n          } catch {\n            /* 单个服务商列不出模型：留空即可（下拉框里该服务商只有「跟随当前对话」可选） */\n          }\n          return { ...p, models };\n        }),\n      );\n      return okResult({ providers: catalog });\n    } catch (e) {\n      // 模型目录取不到是依赖不可用（宿主没提供 llm 适配器 / 全部列模型失败），不是传输层故障\n      return failResult('generate-error', e instanceof Error ? e.message : String(e));\n    }\n  }\n\n  // 轮询状态（/state，GET，no-cache）是前端轮询的唯一数据源：只读、纯内存、零副作用——\n  // 在这里触发外部调用或模型生成会把所有人的轮询拖死；也不碰磁盘（配置变更信号走 sections.config）。\n  //\n  // 长轮询：带 `?since=&timeout=`（成对必填）时，版本与当前相同就挂起，直到任意叶子被写过或超时；\n  // 不带 = 立刻返回全量。等待语义与 GET /playback/{id} 的 wait 同一套（上限同值、断线同一个 signal）。\n  if (rest === 'state') {\n    if (method !== 'GET') return methodNotAllowed();\n    const headers = { 'cache-control': 'no-cache, no-store' };\n    const parsed = parseStateWaitQuery(url.searchParams.get('since'), url.searchParams.get('timeout'));\n    // since/timeout 是业务参数：给错了是调用方的问题，但仍属「请求已进处理器」\n    if (parsed.kind === 'error') return failResult('bad-request', parsed.error);\n    const current = state.read();\n    // 两者都没传 → 立刻返回；已经有新东西 → 也立刻返回（别白等一整个 timeout）。\n    // timeout=0 走挂起分支，下一拍就醒，等价「立刻返回」，这里不特判。\n    if (parsed.kind === 'none' || current.counter !== parsed.since) {\n      return okResult(current, headers);\n    }\n    const since = parsed.since;\n    return await new Promise<RouteResult>((resolveWait) => {\n      let settled = false;\n      /** 收尾：只认第一次（唤醒 / 超时 / 取消 / 调用方断开 都可能先后到达） */\n      const settle = (result: RouteResult): void => {\n        if (settled) return;\n        settled = true;\n        resolveWait(result);\n      };\n      // 唤醒时才 read()：store 保证「叶子已写定」之后才叫醒，所以这里拿到的一定是新状态\n      const cancel = state.wait({\n        since,\n        timeoutMs: parsed.timeoutMs,\n        onWake: () => settle(okResult(state.read(), headers)),\n      });\n      // 调用方断开：取消等待者（清掉它的超时定时器），以「无需应答」收尾。\n      const onAbort = (): void => {\n        cancel();\n        settle({ kind: 'none' });\n      };\n      if (signal?.aborted) {\n        onAbort();\n        return;\n      }\n      signal?.addEventListener('abort', onAbort, { once: true });\n    });\n  }\n\n  // 外部写入工作状态：POST 设置固定外部槽 `api` 的档位（task 省略 = 保留，null = 清空），\n  // DELETE 清空回空闲（幂等）。只解决「外部程序把状态告诉桌宠」，不做多写者仲裁/租约/会话管理；\n  // 外部槽与会话一起参与现有优先级（waiting > error > working > thinking > result > success）。\n  if (rest === 'work-status') {\n    if (method === 'DELETE') {\n      if (workStatus.clear(EXTERNAL_WORK_SESSION)) publishWorkStatus();\n      return { kind: 'text', status: 204, body: '' };\n    }\n    if (method !== 'POST') return methodNotAllowed();\n    if (Buffer.byteLength(body ?? '', 'utf8') > 8 * 1024) return payloadTooLarge('body too large');\n    let parsed: unknown;\n    try {\n      parsed = JSON.parse(body ?? '');\n    } catch {\n      return invalidJson();\n    }\n    if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) return invalidJson();\n    const payload = parsed as { state?: unknown; task?: unknown };\n    const state = payload.state;\n    if (typeof state !== 'string' || !(HOST_WORK_STATUS_STATES as readonly string[]).includes(state))\n      return failResult('bad-request', `state 必须是 ${HOST_WORK_STATUS_STATES.join(' / ')} 之一`);\n    let task: string | null | undefined;\n    if (Object.prototype.hasOwnProperty.call(payload, 'task')) {\n      if (payload.task === null) {\n        task = null;\n      } else if (typeof payload.task === 'string') {\n        const trimmed = payload.task.trim();\n        if (trimmed === '') {\n          task = null;\n        } else if (Array.from(trimmed).length > TASK_TEXT_MAX) {\n          return failResult('bad-request', `task too long (max ${TASK_TEXT_MAX} code points)`);\n        } else {\n          task = trimmed;\n        }\n      } else {\n        return failResult('bad-request', 'invalid task');\n      }\n    }\n    workStatus.setState(EXTERNAL_WORK_SESSION, state as HostWorkStatusState, nextExternalWorkSeq());\n    if (task !== undefined) workStatus.setTask(EXTERNAL_WORK_SESSION, task);\n    publishWorkStatus();\n    return okResult({\n      state: workStatus.stateOf(EXTERNAL_WORK_SESSION) ?? state,\n      task: workStatus.taskOf(EXTERNAL_WORK_SESSION),\n    });\n  }\n\n  return undefined;\n}\n"
    },
    {
      "path": "dsh-pet/src/shared/state.ts",
      "content": "/**\n * 轮询状态（/state）的客户端侧纯逻辑：拉取、叶子拍平、与基线比对。\n * 不负责写状态——动作端点只回执，数据只有一个出口；路径只按已知前后缀解析成落点\n * （见 resolveLeafPath），绝不按点号切分，因为宠物 id 允许含点号。\n * 两端共用同一份；首拉只记基线不渲染，否则刷新页面会把旧气泡重放一遍。\n * @module dsh-pet/src/shared/state\n */\nimport { toBalanceState, type BalanceState } from './balance/index.ts';\nimport { toWorkStatus, type WorkStatusSnapshot } from './work-status.ts';\nimport { ROUTE_PATH } from './constants.ts';\n\n/** 一个叶子：计数器 + 载荷；data 为 null 表示还没有数据，消费端跳过。 */\nexport interface StateLeaf {\n  counter: number;\n  data: unknown;\n}\n\n/** 轮询状态的客户端视图（叶子已规范化：counter 必为数字）。 */\nexport interface PollState {\n  /** 整份 S 的版本号（= 最后一次写入的编号），回传成 ?since= 表达「我手里这份是哪个版本」。\n   *  老宿主不带此字段 → undefined：消费端据此退回定时轮询——老宿主不认识 since/timeout，\n   *  会立刻返回，不退避就变成狂打。 */\n  counter?: number;\n  sections: Record<string, StateLeaf>;\n  pets: Record<string, Record<string, StateLeaf>>;\n}\n\n/** 一次变化的叶子（path 供日志与调试，leaf 供渲染）。 */\nexport interface StateChange {\n  path: string;\n  leaf: StateLeaf;\n}\n\n/** 叶子规范化：形状不对（非对象或 counter 非数字）→ null，不让脏数据进渲染层。 */\nfunction normLeaf(value: unknown): StateLeaf | null {\n  if (!value || typeof value !== 'object') return null;\n  const leaf = value as { counter?: unknown; data?: unknown };\n  if (typeof leaf.counter !== 'number' || !Number.isFinite(leaf.counter)) return null;\n  return { counter: leaf.counter, data: leaf.data ?? null };\n}\n\n/** 拉一次 /state；失败、HTTP 非 2xx 或形状不对都返回 null（轮询侧静默重试）。\n *  wait 传了就带 ?since=&timeout= 走长轮询：宿主在版本没变时挂起，直到任意叶子被写过或超时；\n *  不传则立刻返回全量。 */\nexport async function fetchState(\n  baseUrl = ROUTE_PATH + '/state',\n  wait?: { since: number; timeoutMs: number },\n): Promise<PollState | null> {\n  try {\n    const url = wait ? `${baseUrl}?since=${wait.since}&timeout=${wait.timeoutMs}` : baseUrl;\n    const res = await fetch(url, { cache: 'no-store' });\n    if (!res.ok) return null;\n    const raw = (await res.json().catch(() => null)) as {\n      ok?: unknown;\n      counter?: unknown;\n      sections?: unknown;\n      pets?: unknown;\n    } | null;\n    // 业务失败也是 200：`ok:false` 的体不是快照，按失败处理（否则会被当成「空状态」成功一次）\n    if (!raw || typeof raw !== 'object' || raw.ok === false) return null;\n    const sections: Record<string, StateLeaf> = {};\n    const rawSections =\n      raw.sections && typeof raw.sections === 'object' ? (raw.sections as Record<string, unknown>) : {};\n    for (const [name, value] of Object.entries(rawSections)) {\n      const leaf = normLeaf(value);\n      if (leaf) sections[name] = leaf;\n    }\n    const pets: Record<string, Record<string, StateLeaf>> = {};\n    const rawPets = raw.pets && typeof raw.pets === 'object' ? (raw.pets as Record<string, unknown>) : {};\n    for (const [petId, entry] of Object.entries(rawPets)) {\n      if (!entry || typeof entry !== 'object') continue;\n      const leaves: Record<string, StateLeaf> = {};\n      for (const [name, value] of Object.entries(entry as Record<string, unknown>)) {\n        const leaf = normLeaf(value);\n        if (leaf) leaves[name] = leaf;\n      }\n      pets[petId] = leaves;\n    }\n    return {\n      counter: typeof raw.counter === 'number' && Number.isFinite(raw.counter) ? raw.counter : undefined,\n      sections,\n      pets,\n    };\n  } catch {\n    return null;\n  }\n}\n\n/** 遍历 S 的所有叶子（sections 在前、pets 在后）。 */\nfunction* walkLeaves(s: PollState): Generator<[string, StateLeaf]> {\n  for (const [name, leaf] of Object.entries(s.sections ?? {})) yield ['sections.' + name, leaf];\n  for (const [petId, leaves] of Object.entries(s.pets ?? {})) {\n    for (const [name, leaf] of Object.entries(leaves ?? {})) yield ['pets.' + petId + '.' + name, leaf];\n  }\n}\n\n/** S → { 叶子路径: counter }，首拉基线用；新增的 section 或宠物自动纳入。 */\nexport function flattenCounters(s: PollState): Record<string, number> {\n  const out: Record<string, number> = {};\n  for (const [path, leaf] of walkLeaves(s)) out[path] = leaf.counter;\n  return out;\n}\n\n/** 与基线比对并就地推进基线，返回本次变化的叶子。\n *  首拉不要调它（用 flattenCounters 记基线），否则页面刷新会把旧数据重放一遍。 */\nexport function takeChanged(s: PollState, baseline: Record<string, number>): StateChange[] {\n  const out: StateChange[] = [];\n  for (const [path, leaf] of walkLeaves(s)) {\n    if (baseline[path] === leaf.counter) continue;\n    baseline[path] = leaf.counter;\n    out.push({ path, leaf });\n  }\n  return out;\n}\n\n/** `sections.<名>` 里会被消费端分发的那几个叶子。 */\nexport type SectionLeafName = 'config' | 'balance' | 'workStatus' | 'notify' | 'menu';\n\n/** `pets.<id>.<名>` 里会被消费端分发的那几个叶子。 */\nexport type PetLeafName = 'say' | 'anim' | 'position' | 'throw' | 'lock' | 'sleep';\n\n/** 一次叶子分发的落点：分段叶子，或某只宠物的叶子。 */\nexport type LeafTarget =\n  { where: 'section'; name: SectionLeafName } | { where: 'pet'; name: PetLeafName; petId: string };\n\n/** 分段叶子名的全集；新增 section 叶子时与 {@link SectionLeafName} 一起改。 */\nconst SECTION_LEAF_NAMES = ['config', 'balance', 'workStatus', 'notify', 'menu'] as const;\n\n/** 宠物叶子名的全集；新增宠物叶子时与 {@link PetLeafName} 一起改。 */\nconst PET_LEAF_NAMES = ['say', 'anim', 'position', 'throw', 'lock', 'sleep'] as const;\n\n/** 把字符串收窄成分段叶子名。 */\nfunction isSectionLeafName(name: string): name is SectionLeafName {\n  return (SECTION_LEAF_NAMES as readonly string[]).includes(name);\n}\n\n/** 把字符串收窄成宠物叶子名。 */\nfunction isPetLeafName(name: string): name is PetLeafName {\n  return (PET_LEAF_NAMES as readonly string[]).includes(name);\n}\n\n/**\n * 把叶子路径解析成落点；不认识的（含空宠物 id、空叶子名）→ null，消费端跳过这一拍。\n *\n * 宠物 id 允许含点号，所以只按**最后一个**点切叶子名，绝不 `split('.')`：`pets.a.b.say` 的宠物是\n * `a.b`。规则在这里而不是在分发处，是为了能脱离 React 断言——两端共用同一份口径。\n */\nexport function resolveLeafPath(path: string): LeafTarget | null {\n  if (path.startsWith('sections.')) {\n    const name = path.slice('sections.'.length);\n    return isSectionLeafName(name) ? { where: 'section', name } : null;\n  }\n  if (!path.startsWith('pets.')) return null;\n  const rest = path.slice('pets.'.length);\n  const dot = rest.lastIndexOf('.');\n  // dot ≤ 0：没有叶子名（`pets.a`）或宠物 id 为空（`pets..say`）——都不是合法落点。\n  if (dot <= 0) return null;\n  const name = rest.slice(dot + 1);\n  return isPetLeafName(name) ? { where: 'pet', name, petId: rest.slice(0, dot) } : null;\n}\n\n/** 类型收窄：余额叶子 → `{ state, manual }`。\n *  manual = 这次写入是手动触发的（/balance 命令、桌面「查看余额」菜单），由宿主在写入时标记，\n *  消费端据此决定余额不可用时要不要必弹文字说明。形状非法 → null，消费端跳过这一拍。 */\nexport function readBalance(leaf: StateLeaf): { state: BalanceState; manual: boolean } | null {\n  const state = toBalanceState(leaf.data);\n  if (!state) return null;\n  const manual = (leaf.data as { manual?: unknown }).manual === true;\n  return { state, manual };\n}\n\n/** 说话指令（`pets.<id>.say` 的两种形态）。\n *  say：弹一个气泡，duration = 显示时长（毫秒；缺省 10s，0 = 字面意思「不显示」），\n *  anim 只在显式 false 时出现，表示这次不联动 events.whisper 动画、只弹气泡。\n *  clear：收起当前气泡（POST /bubble/clear 的落点），必须是单独形态——空文本会被判成非法、整拍跳过。\n *  配图两种形态并列、由字段名区分：image = 表情包池内的名称（消费端拼图片路径），url = 第三方给的完整地址。\n *  不做「一个中性字段装两种值」：消费端必须知道该不该拼路径，靠 startsWith('http') 嗅探在名字像 URL 时会出错。\n *  voiceTo：宿主指定这一句该由哪一端念（目前只有周期碎碎念与待办提醒写入）；缺省 = 谁都不念。\n */\nexport type SayCue =\n  | {\n      kind: 'say';\n      text: string;\n      image?: string;\n      url?: string;\n      duration?: number;\n      anim?: boolean;\n      voiceTo?: VoiceTarget;\n    }\n  | { kind: 'clear' };\n\n/** 一次说话该由哪一端念；与 src/host/surface 的同名联合体是两份（宿主不 import src/shared），改动时两边一起改。 */\nexport type VoiceTarget = 'web' | 'desktop';\n\n/** 类型收窄：宠物说话叶子 → SayCue（形状非法或空文本 → null，消费端跳过这一拍）。\n *  碎碎念、命令气泡、对话回复共用这一个叶子——前端本来就是同一条展示链路。\n *  duration 与 anim 缺省即默认行为（10s + 联动），不写这两个字段的叶子照常能读。 */\nexport function readSay(leaf: StateLeaf): SayCue | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as {\n    text?: unknown;\n    image?: unknown;\n    url?: unknown;\n    duration?: unknown;\n    anim?: unknown;\n    voiceTo?: unknown;\n    clear?: unknown;\n  };\n  // 清空指令优先：它不带 text，所以必须排在文本校验前面\n  if (d.clear === true) return { kind: 'clear' };\n  if (typeof d.text !== 'string' || !d.text) return null;\n  return {\n    kind: 'say',\n    text: d.text,\n    image: typeof d.image === 'string' ? d.image : undefined,\n    // 第三方给的配图地址（完整 URL，scheme 已由宿主卡在 http/https）。与 image 并列、互斥，\n    // 消费端有 url 就用 url，否则拼表情包路径——判别位在字段名上，见 SayCue 的说明。\n    url: typeof d.url === 'string' ? d.url : undefined,\n    // 只认 ≥0 的有限数：非法值当没给（写端已校验，这里只是防御，不让脏数据毁掉整拍）\n    duration: typeof d.duration === 'number' && Number.isFinite(d.duration) && d.duration >= 0 ? d.duration : undefined,\n    anim: typeof d.anim === 'boolean' ? d.anim : undefined,\n    // 只认两个合法字面量：写错的一端名等于「不指定」，消费端据此不念\n    voiceTo: d.voiceTo === 'web' || d.voiceTo === 'desktop' ? d.voiceTo : undefined,\n  };\n}\n\n/** 类型收窄：工作状态叶子 → 快照（形状非法 → null，消费端跳过这一拍）。\n *  与余额不同没有「手动」标记：工作状态永远由 DSH 事件驱动，没有用户主动要的那条路。 */\nexport function readWorkStatus(leaf: StateLeaf): WorkStatusSnapshot | null {\n  return toWorkStatus(leaf.data);\n}\n\n/** 朝向：left = 素材原样，right = 镜像（渲染端贴 scaleX(-1)）。\n *  与宿主半侧的同名联合体是两份（宿主不 import 本目录），改动时两边要一起改。 */\nexport type PetFacing = 'left' | 'right';\n\n/** 类型收窄：点播动画叶子 → 动画名或地址 + 播放回执（两者都空 → null，消费端跳过这一拍）。\n *  name：该宠物动画池内的名字，名字即文件名，消费端换源并走菜单动作处理（镜像修正、移动类走真实位移）；\n *  url：第三方给的完整地址，直接换源播一次、不走菜单语义——裸地址没有「是不是文字类/移动类」这些属性。\n *  「这个动画是否存在于该宠物」由宿主在写入前保证，播放端不兜底。\n *  playbackId 是宿主受理时生成的回执编号，渲染端在播放的四个时机上报真实状态；\n *  老宿主不写这个字段 → undefined，按「无回执」处理。\n *  facing 是调用方显式指定的朝向：undefined = 没指定，不动朝向，保持当前朝向——不是回落 left。 */\nexport function readAnim(\n  leaf: StateLeaf,\n): { name?: string; url?: string; playbackId?: string; facing?: PetFacing } | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as { name?: unknown; url?: unknown; playbackId?: unknown; facing?: unknown };\n  const name = typeof d.name === 'string' && d.name ? d.name : undefined;\n  const url = typeof d.url === 'string' && d.url ? d.url : undefined;\n  // 两个都缺席 = 形状非法（宿主写端保证恰好一个，这里不替它猜）\n  if (name === undefined && url === undefined) return null;\n  return {\n    name,\n    url,\n    playbackId: typeof d.playbackId === 'string' && d.playbackId ? d.playbackId : undefined,\n    // 朝向：只认两个字面量，其余（含缺省、老宿主、脏值）一律 undefined = 不动朝向\n    facing: d.facing === 'left' || d.facing === 'right' ? d.facing : undefined,\n  };\n}\n\n/** 占用锁叶子的形态：`{ locked: true, expiresAt }` = 正被第三方占用，`{ locked: false }` = 没有占用。 */\nexport type LockState = { locked: true; expiresAt: number } | { locked: false };\n\n/** 类型收窄：占用锁叶子 → LockState（形状非法 → null，消费端跳过这一拍）。\n *\n *  这是状态不是指令：宿主写、渲染端读来决定要不要冻结自己——随机链不掷骰、暂停自播动画、\n *  忽略自动来源的余额与工作状态表现。宿主停不掉一段正在播的视频，「完全静止」最终由渲染端执行。\n *\n *  宿主不会到点推一次「锁没了」：expiresAt 是唯一真相，渲染端据此自己定时解除（宿主侧过期是懒判的）。\n *  读到已经过去的 expiresAt 就等于没有锁——刷新页面后拿到陈旧叶子时必须按这个判，不能只看 locked。\n *  不含 lockId：那是持锁者的凭证，不能放进人人可读的 /state。\n */\nexport function readLock(leaf: StateLeaf): LockState | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as { locked?: unknown; expiresAt?: unknown };\n  if (d.locked === false) return { locked: false };\n  if (d.locked !== true) return null;\n  // locked:true 却缺 expiresAt（或非法）= 形状非法：宁可不冻结，也不猜一个到期时刻\n  if (typeof d.expiresAt !== 'number' || !Number.isFinite(d.expiresAt)) return null;\n  return { locked: true, expiresAt: d.expiresAt };\n}\n\n/** 睡觉叶子的形态：`{ sleeping: true, start, loop, end }` = 正在睡（三段名由宿主挑定），\n *  `{ sleeping: false }` = 醒着。 */\nexport type SleepState = { sleeping: true; start: string; loop: string; end: string } | { sleeping: false };\n\n/** 类型收窄：睡觉叶子 → SleepState（形状非法 → null，消费端跳过这一拍）。\n *\n *  这是状态不是指令：渲染端读它决定要不要睡，不往回写。三段名字由宿主挑定并一起写进叶子，\n *  渲染端照此播「开始（一次）→ 循环（无限）→ 起来（一次）」——自己重新挑会让两端播到不同的一套。\n *  `sleeping: true` 却缺任何一段名 = 形状非法：宁可不睡（保持现状），也不要播一段不存在的动画。\n */\nexport function readSleep(leaf: StateLeaf): SleepState | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as { sleeping?: unknown; start?: unknown; loop?: unknown; end?: unknown };\n  if (d.sleeping === false) return { sleeping: false };\n  if (d.sleeping !== true) return null;\n  for (const name of [d.start, d.loop, d.end]) {\n    if (typeof name !== 'string' || name === '') return null;\n  }\n  return { sleeping: true, start: d.start as string, loop: d.loop as string, end: d.end as string };\n}\n\n/** 位置指令的运动模式（三选一）。与宿主半侧的同名联合体是两份，改动时两边要一起改。 */\nexport type PositionMode = 'instant' | 'spring' | 'line';\n\n/** 类型收窄：位置指令叶子 → `{ x, y, mode, duration }`（形状非法 → null，消费端跳过这一拍）。\n *  这是指令不是状态上报：宿主写、前端读来挪宠物，前端不往回写。\n *  x/y 是宠物中心的归一化坐标（0~1，宿主写入前已夹取）；duration 只有 line 模式才有，其余恒为 0。 */\nexport function readPosition(leaf: StateLeaf): { x: number; y: number; mode: PositionMode; duration: number } | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as { x?: unknown; y?: unknown; mode?: unknown; duration?: unknown };\n  if (typeof d.x !== 'number' || !Number.isFinite(d.x)) return null;\n  if (typeof d.y !== 'number' || !Number.isFinite(d.y)) return null;\n  if (d.mode !== 'instant' && d.mode !== 'spring' && d.mode !== 'line') return null;\n  if (d.mode === 'line') {\n    // line 缺 duration（或非法）就是形状非法：宿主一定会写，写错宁可跳过这一拍，也不替它猜一个时间\n    if (typeof d.duration !== 'number' || !Number.isFinite(d.duration) || d.duration < 0) return null;\n    return { x: d.x, y: d.y, mode: 'line', duration: d.duration };\n  }\n  return { x: d.x, y: d.y, mode: d.mode, duration: 0 };\n}\n\n/** 类型收窄：抛掷指令叶子 → `{ angle, power }`（形状非法 → null，消费端跳过这一拍）。\n *  angle 单位为度（0 = 正右，逆时针为正）；power 是力度倍率（1.0 = 1200 px/s 软钳速前）。\n *  同样是指令，前端不往回写。 */\nexport function readThrow(leaf: StateLeaf): { angle: number; power: number } | null {\n  if (!leaf.data || typeof leaf.data !== 'object') return null;\n  const d = leaf.data as { angle?: unknown; power?: unknown };\n  if (typeof d.angle !== 'number' || !Number.isFinite(d.angle)) return null;\n  if (typeof d.power !== 'number' || !Number.isFinite(d.power) || d.power <= 0) return null;\n  return { angle: d.angle, power: d.power };\n}\n\n/** 动作端点：POST 一次，返回是否成功。\n *  动作不返回数据——数据只有 /state 一个出口。调用方收到 ok 后不需要再做别的：动作写叶子会让\n *  顶层 counter 变化，挂着的长轮询那一拍立刻返回。 */\nexport async function postAction(baseUrl: string, body?: unknown): Promise<boolean> {\n  try {\n    const res = await fetch(baseUrl, {\n      method: 'POST',\n      ...(body === undefined ? {} : { headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) }),\n    });\n    if (!res.ok) return false;\n    const data = (await res.json().catch(() => null)) as { ok?: unknown } | null;\n    return data?.ok === true;\n  } catch {\n    return false;\n  }\n}\n"
    }
